import{L as M,en as m$1,m as F,on as oc,qt as ie}from"./chunk-CNoI8Cuz.js";var p=[{id:1,slug:`position-de-base-et-appuis`,module:1,title:`Position de base et appuis`,level:`découverte`,durationMin:15,objective:`Trouver une position de boxe stable : pieds décalés, poids réparti, genoux souples. Savoir s’y replacer seul après chaque mouvement.`,prerequisites:[`Savoir se tenir debout en équilibre sur un pied quelques secondes`,`Connaître sa main forte`],organisation:{space:`Salle libre ou ring, chaque boxeur sur une ligne au sol avec 2 m autour de lui`,material:[`Lignes de scotch au sol (une par boxeur)`,`Miroir mural si disponible`],groups:`Individuel, en ligne face à l’éducateur`},schema:{kind:`appuis`,phases:[`Pieds sur la ligne`,`Décalage et quart de tour`,`Fléchir et équilibrer`]},steps:[`Pieds parallèles sur la ligne, écartés largeur d’épaules ; l’éducateur montre le pied avant (opposé à la main forte).`,`Reculer le pied arrière d’un pas et le décaler sur le côté : talon arrière décollé, pointes orientées vers l’avant à 45° (5 répétitions lentes).`,`Fléchir légèrement les genoux, poids réparti 50/50, buste droit ; tenir 20 s, relâcher, recommencer 4 fois.`,`Jeu du « coup de vent » : l’éducateur annonce « vent », chacun se met en équilibre sur un pied puis revient en position en moins de 2 s (8 fois).`,`Marche libre dans la salle ; au signal sonore, se figer en position de base. Vérification croisée avec un voisin à distance (3 min).`],decision:`Au signal, le boxeur choisit seul s’il doit corriger sa largeur d’appuis ou son orientation avant de lever la main pour dire « prêt ».`,corrections:[{error:`Pieds sur la même ligne (position « sur un fil »), équilibre latéral fragile.`,fix:`Écarter les pieds de part et d’autre de la ligne au sol, comme sur des rails de train.`},{error:`Jambes tendues et talons au sol.`,fix:`Fléchir comme pour s’asseoir sur un tabouret haut et décoller légèrement le talon arrière.`}],criteria:[`Les deux pieds sont de part et d’autre de la ligne, écartés à peu près de la largeur des épaules.`,`Les genoux restent fléchis pendant les 20 s de maintien.`,`Le boxeur retrouve sa position en moins de 2 s après le jeu du « coup de vent ».`],adaptations:{enfants:`Marquer les emplacements des pieds avec des empreintes ou des plots de couleur ; maintiens de 10 s seulement et beaucoup de jeu de statues.`,ados:`Faire filmer sa position par un camarade au téléphone (avec accord) puis la comparer au modèle de l’éducateur.`,jeunesAdultes:`Ajouter des transferts de poids lents avant/arrière en gardant la position, 3 séries de 30 s.`},safety:`Sol sec et dégagé, chaussures fermées ou pieds nus selon la salle ; écart de 2 m entre boxeurs pour les phases d’équilibre.`},{id:2,slug:`la-garde-mains-coudes-menton`,module:1,title:`La garde : mains, coudes, menton`,level:`découverte`,durationMin:15,objective:`Construire une garde protectrice et détendue : mains à hauteur des pommettes, coudes près du corps, menton rentré. La conserver en bougeant.`,prerequisites:[`Position de base et appuis`],organisation:{space:`Face au miroir ou en cercle, 2 m entre chaque boxeur`,material:[`Miroir mural`,`Gommettes de couleur (repère pommette)`],groups:`Individuel puis binômes à distance (2 m) pour l’observation`},schema:{kind:`appuis`,phases:[`Mains aux pommettes`,`Coudes fermés`,`Menton et regard`]},steps:[`En position de base, poser les poings fermés sans serrer contre les pommettes ; main avant un peu plus avancée (10 s, 4 fois).`,`Coudes vers le bas, collés aux côtes ; l’éducateur montre les « portes » qui se ferment de chaque côté du corps.`,`Rentrer légèrement le menton, regard à travers les gants vers un point du miroir ; épaules relâchées (respirer 5 fois calmement).`,`Statue-garde : marcher, au signal reprendre la garde complète le plus vite possible, le binôme annonce ce qui manque (6 fois chacun).`,`Garder la garde 30 s en faisant de petits pas sur place, puis 30 s de relâchement ; 3 cycles.`],decision:`Le binôme observateur doit choisir et annoncer le seul point de garde le plus important à corriger chez son partenaire.`,corrections:[{error:`Mains qui descendent vers la poitrine dès que l’attention baisse.`,fix:`Repère gommette sur la pommette : le poing doit « toucher » la gommette sans pression.`},{error:`Coudes ouverts sur les côtés, épaules crispées.`,fix:`Laisser tomber les épaules en expirant, imaginer tenir une feuille entre coude et côtes.`},{error:`Menton levé, regard au plafond.`,fix:`Regarder le haut de ses gants dans le miroir, menton orienté vers la clavicule.`}],criteria:[`Les poings sont à hauteur des pommettes pendant 30 s de déplacement sur place.`,`Les coudes restent à moins d’une main des côtes.`,`Le menton est rentré et le regard dirigé vers l’avant.`],adaptations:{enfants:`Garde « du chevalier » : les mains sont un casque, les coudes un bouclier ; maintiens courts de 15 s.`,ados:`Défi en binôme : qui garde la garde la plus propre pendant 45 s de pas sur place, jugé par un troisième élève.`,jeunesAdultes:`Travail les yeux fermés 10 s puis vérification au miroir, pour construire la sensation interne de la garde.`},safety:`Pas de serrage des poings prolongé ni de crispation des épaules ; pause dès qu’apparaît une gêne au cou ou aux épaules.`},{id:3,slug:`pas-chasse-avant-arriere`,module:1,title:`Pas chassé avant et arrière`,level:`découverte`,durationMin:15,objective:`Avancer et reculer en pas chassés sans croiser ni joindre les pieds, en conservant la garde et la largeur d’appuis.`,prerequisites:[`Position de base et appuis`,`La garde : mains, coudes, menton`],organisation:{space:`Couloirs de 6 m marqués au sol, un par boxeur ou par binôme alterné`,material:[`Lignes au sol`,`Plots en début et fin de couloir`],groups:`Vagues de 4 à 6 boxeurs qui traversent puis reviennent`},schema:{kind:`deplacement`,phases:[`Le pied avant pousse vers l’avant`,`Le pied arrière suit`,`Retour en position`]},steps:[`Démonstration au ralenti : pour avancer, le pied avant part en premier, le pied arrière suit de la même distance.`,`Avancer de 5 petits pas chassés en comptant à voix haute, s’arrêter en garde ; revenir de 5 pas en reculant (pied arrière en premier).`,`Couloir aller-retour 4 fois, en gardant la tête à la même hauteur (pas de rebond).`,`Varier l’amplitude : 3 petits pas, 2 grands pas, sur annonce de l’éducateur.`,`Jeu des feux : vert = avancer, rouge = s’arrêter en garde, orange = reculer ; 2 min.`],decision:`Au feu orange, le boxeur choisit le nombre de pas de recul nécessaire pour ne pas dépasser le plot de fin de couloir.`,corrections:[{error:`Le pied arrière dépasse ou rejoint le pied avant.`,fix:`Garder un « écart de sécurité » constant : les pieds ne se touchent jamais, comme deux aimants qui se repoussent.`},{error:`Le boxeur saute à pieds joints.`,fix:`Faire glisser l’avant du pied au sol, pas de phase d’envol.`}],criteria:[`Les pieds ne se croisent ni ne se rejoignent sur 5 pas consécutifs.`,`La garde reste haute pendant toute la traversée.`,`Le boxeur s’arrête en position stable au feu rouge.`],adaptations:{enfants:`Couloir décoré de cerceaux plats à franchir pas à pas ; histoire du « crabe qui marche droit ».`,ados:`Chronométrer un aller-retour propre ; toute erreur de pieds ajoute une pénalité de 2 s.`,jeunesAdultes:`Enchaîner 3 allers-retours sans pause en gardant un rythme régulier, puis 30 s de récupération.`},safety:`Reculer uniquement dans un couloir vérifié libre ; jamais de recul rapide vers un mur ou un autre groupe.`},{id:4,slug:`pas-chasse-lateral`,module:1,title:`Pas chassé latéral`,level:`découverte`,durationMin:15,objective:`Se déplacer à gauche et à droite en partant du pied le plus proche de la direction, sans croiser les jambes.`,prerequisites:[`Pas chassé avant et arrière`],organisation:{space:`Rangées de 4 plots espacés de 1 m, une rangée par boxeur`,material:[`Plots (4 par boxeur)`,`Lignes au sol perpendiculaires`],groups:`Individuel, en parallèle sur toute la largeur de la salle`},schema:{kind:`deplacement`,phases:[`Pied du côté choisi`,`L’autre pied suit`,`Garde face à l’avant`]},steps:[`Règle clé : vers la gauche, pied gauche en premier ; vers la droite, pied droit en premier. Démonstration lente face au groupe.`,`Passer d’un plot à l’autre en pas latéraux (4 plots aller, 4 retour), buste face à l’avant, 3 fois.`,`Ajouter un arrêt en garde de 2 s devant chaque plot.`,`Combiner : 2 pas latéraux, 1 pas avant, 1 pas arrière, sur un tracé en « L ».`,`L’éducateur pointe une direction avec le bras ; chacun réagit par un pas chassé dans la bonne direction (15 appels).`],decision:`Sur l’appel visuel, choisir instantanément le bon pied de départ selon la direction indiquée.`,corrections:[{error:`Jambes qui se croisent pendant le déplacement.`,fix:`Dire à voix basse « ouvre, ferme » : on ouvre avec le pied du côté choisi, on referme avec l’autre sans le croiser.`},{error:`Le buste se tourne dans le sens de la marche.`,fix:`Fixer un repère au mur devant soi et ne jamais le quitter des yeux.`}],criteria:[`Le premier pied qui bouge est celui du côté du déplacement dans 4 cas sur 5.`,`Aucun croisement de jambes sur le tracé de plots.`,`Le buste reste orienté vers l’avant.`],adaptations:{enfants:`Plots de couleur : l’éducateur annonce une couleur, l’enfant s’y rend en pas latéraux.`,ados:`Version miroir avec l’éducateur : reproduire ses pas latéraux avec moins de 1 s de retard.`,jeunesAdultes:`Augmenter la cadence : 20 s d’appels rapides, 20 s de repos, 4 séries.`},safety:`Espace latéral suffisant entre les rangées de plots (au moins 2 m) pour éviter les collisions lors des réactions rapides.`},{id:5,slug:`pivots-sur-appui-avant`,module:1,title:`Pivots sur l’appui avant`,level:`intermédiaire`,durationMin:20,objective:`Changer d’angle en pivotant sur l’avant du pied avant, en déplaçant le pied arrière en arc de cercle, sans perdre la garde.`,prerequisites:[`Pas chassé latéral`,`La garde : mains, coudes, menton`],organisation:{space:`Un cerceau posé au sol par boxeur, 3 m entre chaque cerceau`,material:[`Cerceaux plats`,`Repères de couleur sur le mur (4 points cardinaux)`],groups:`Individuel, puis binômes observateur/acteur`},schema:{kind:`appuis`,phases:[`Pied avant dans le cerceau`,`Arc du pied arrière`,`Nouvel angle en garde`]},steps:[`Pied avant dans le cerceau ; pivoter sur la pointe de ce pied, le pied arrière décrit un quart de cercle (8 pivots lents, côté fermé).`,`Même travail vers le côté ouvert, 8 répétitions ; vérifier que la largeur d’appuis ne change pas.`,`Pivot d’un quart de tour pour faire face au repère suivant au mur, tour complet en 4 pivots (3 tours).`,`Enchaîner pas chassé avant, pivot, pas chassé arrière ; 6 répétitions de chaque côté.`,`Le binôme montre un repère mural ; l’acteur pivote pour lui faire face en un ou deux pivots (10 appels, puis inversion).`],decision:`Face au repère annoncé, choisir entre un pivot unique plus ample ou deux pivots courts pour rester équilibré.`,corrections:[{error:`Le pied avant sort du cerceau pendant le pivot.`,fix:`Garder la pointe du pied avant « vissée » au sol, seul le talon tourne.`},{error:`Le pied arrière se rapproche, la base devient étroite.`,fix:`Imaginer un compas : le pied arrière garde la même distance en traçant son arc.`}],criteria:[`Le pied avant reste dans le cerceau sur 8 pivots consécutifs.`,`La garde est conservée pendant le pivot.`,`Après chaque pivot, la position de base est identique à celle de départ.`],adaptations:{enfants:`Le cerceau est une « horloge » : on pivote pour pointer midi, trois heures, six heures avec le pied arrière.`,ados:`Compter combien de pivots propres on enchaîne en 30 s, puis chercher à battre son score sans perdre la qualité.`,jeunesAdultes:`Pivots combinés à un pas latéral de sortie, en cherchant la fluidité du mouvement complet.`},safety:`Pivoter sur l’avant du pied, jamais genou bloqué ; sol non glissant obligatoire et lacets vérifiés avant l’atelier.`},{id:6,slug:`direct-bras-avant-dans-le-vide`,module:1,title:`Direct du bras avant dans le vide`,level:`intermédiaire`,durationMin:20,objective:`Coordonner l’extension du bras avant avec un léger transfert de poids, puis revenir en garde par le même chemin, sans aucune cible de contact.`,prerequisites:[`La garde : mains, coudes, menton`,`Pas chassé avant et arrière`],organisation:{space:`Face au miroir ou à un repère mural, 1,5 m minimum devant soi`,material:[`Miroir`,`Gommettes au mur à hauteur d’épaule (cible visuelle seulement)`],groups:`Individuel en ligne, 2 m entre boxeurs`},schema:{kind:`distance`,phases:[`Garde et regard`,`Extension vers le repère`,`Retour en garde`]},steps:[`Ralenti à 3 temps : le poing part droit vers la gommette, rotation du poing en fin de trajet, retour au visage (10 répétitions).`,`Ajouter le léger transfert de poids vers la jambe avant, sans pencher le buste (10 répétitions).`,`Direct puis retour immédiat en garde : le retour doit être aussi rapide que l’aller (3 séries de 8).`,`Direct en avançant d’un pas chassé : le bras part en même temps que le pied avant (8 répétitions sur couloir).`,`Au signal visuel (main levée de l’éducateur), lancer un direct dans le vide ; main baissée, rester en garde (15 signaux).`],decision:`Sur le signal, choisir entre un direct sur place ou un direct en avançant selon la distance qui sépare le boxeur de son repère au sol.`,corrections:[{error:`Le coude s’ouvre et le poing décrit une courbe.`,fix:`Faire glisser le poing le long d’un rail invisible, coude dans l’axe du poing.`},{error:`L’autre main tombe pendant le direct.`,fix:`Garder la main arrière « collée » à la pommette ; vérification au miroir.`},{error:`Bras verrouillé en extension complète.`,fix:`S’arrêter juste avant la tension complète du coude, épaule relâchée.`}],criteria:[`Le poing suit une trajectoire droite et revient par le même chemin.`,`La main arrière reste en garde pendant tout le mouvement.`,`Le coude n’est jamais verrouillé en fin d’extension.`],adaptations:{enfants:`Direct « de la flèche » vers une gommette ; le nombre de répétitions est réduit à 6 par série avec des pauses ludiques.`,ados:`Travail en binôme observateur : l’un lance au ralenti, l’autre valide trajectoire et retour avant de changer de rôle.`,jeunesAdultes:`Varier les vitesses : 4 directs lents, 4 rapides, en gardant la même trajectoire.`},safety:`Aucun coup vers une personne ou un objet : uniquement dans le vide ; ne jamais verrouiller le coude pour protéger l’articulation.`},{id:7,slug:`direct-bras-arriere-et-rotation`,module:1,title:`Direct du bras arrière et rotation du bassin`,level:`intermédiaire`,durationMin:20,objective:`Lancer le direct arrière dans le vide en organisant la chaîne pied arrière, hanche, épaule, poing, et revenir en garde équilibré.`,prerequisites:[`Direct du bras avant dans le vide`,`Pivots sur l’appui avant`],organisation:{space:`Ligne face au miroir, 2 m entre boxeurs`,material:[`Miroir`,`Ligne au sol sous le pied arrière`],groups:`Individuel puis binômes à distance pour l’observation`},schema:{kind:`appuis`,phases:[`Talon arrière tourne`,`Hanche puis épaule`,`Retour en garde`]},steps:[`Sans les bras : pivoter le talon arrière vers l’extérieur et laisser la hanche tourner, 10 rotations lentes.`,`Ajouter l’épaule : hanche et épaule arrière avancent ensemble, la main reste au visage (8 répétitions).`,`Direct arrière complet au ralenti, poing vers un repère du miroir, retour par le même chemin (3 séries de 6).`,`Alterner direct avant puis direct arrière avec pause de 2 s entre chacun, en contrôlant l’équilibre (10 fois).`,`Le binôme observe trois points (talon, menton, main avant) et donne un retour après chaque série de 5.`],decision:`L’observateur choisit le point technique prioritaire pour la série suivante ; l’acteur décide de ralentir ou non pour l’intégrer.`,corrections:[{error:`Le talon arrière reste bloqué au sol, seul le bras travaille.`,fix:`Penser à « écraser une fourmi » sous la pointe du pied arrière en tournant le talon.`},{error:`Le buste bascule vers l’avant, le poids passe devant le pied avant.`,fix:`Garder la tête au-dessus du genou avant, jamais au-delà.`}],criteria:[`Le talon arrière pivote à chaque direct arrière.`,`Le menton reste protégé derrière l’épaule pendant l’extension.`,`Le boxeur termine équilibré, en position de base, sans pas de rattrapage.`],adaptations:{enfants:`Image du « robot qui tourne » : d’abord le pied, puis le ventre, puis le bras ; séries de 5.`,ados:`Comparaison vidéo lente du mouvement en début et fin de séance (avec accord), pour visualiser la rotation.`,jeunesAdultes:`Rechercher l’enchaînement fluide de la chaîne cinétique sur 3 séries de 8 à vitesse moyenne, sans forcer.`},safety:`Rotation contrôlée sans à-coup sur le genou arrière ; dans le vide uniquement, poing jamais dirigé vers un partenaire.`},{id:8,slug:`changements-de-rythme-en-deplacement`,module:1,title:`Changements de rythme en déplacement`,level:`avancé`,durationMin:20,objective:`Varier la vitesse et l’amplitude des pas chassés (lent, rapide, arrêt) tout en restant prêt à agir à chaque instant.`,prerequisites:[`Pas chassé avant et arrière`,`Pas chassé latéral`,`Pivots sur l’appui avant`],organisation:{space:`Carré de 5 m × 5 m délimité par des plots, un carré pour 2 boxeurs qui alternent`,material:[`Plots`,`Musique ou claquements de mains pour le tempo`,`Chronomètre`],groups:`Binômes qui alternent travail et observation`},schema:{kind:`deplacement`,phases:[`Tempo lent`,`Accélération courte`,`Arrêt en garde`]},steps:[`Déplacement libre dans le carré au tempo lent des claquements, 1 min, garde haute.`,`Sur « vite », 3 pas chassés rapides dans une direction, puis retour au tempo lent (8 fois).`,`Sur « stop », arrêt net en garde équilibrée ; l’observateur vérifie appuis et garde.`,`Séquence imposée : lent-lent-vite-stop-pivot, répétée 6 fois, en changeant de direction à chaque cycle.`,`Round libre de 1 min 30 : le boxeur crée lui-même ses changements de rythme, l’observateur compte les ruptures réussies.`],decision:`Pendant le round libre, le boxeur choisit quand accélérer et dans quelle direction, en tenant compte des limites du carré.`,corrections:[{error:`L’accélération fait perdre la garde et la largeur d’appuis.`,fix:`Raccourcir les pas rapides : la vitesse vient de la fréquence, pas de l’amplitude.`},{error:`Arrêt avec le poids sur une seule jambe.`,fix:`Freiner sur les deux appuis en fléchissant davantage les genoux.`}],criteria:[`Au moins 3 changements de rythme nets en 1 min 30 de round libre.`,`Arrêts stables, sans pas de rattrapage.`,`Garde maintenue pendant les accélérations.`],adaptations:{enfants:`Jeu « tortue / lièvre / statue » avec des cartes illustrées ; rounds de 45 s.`,ados:`L’observateur note un score sur 10 pour la netteté des ruptures ; échange des rôles et discussion.`,jeunesAdultes:`Ajouter un direct avant dans le vide à la fin de chaque accélération, 3 rounds de 1 min 30.`},safety:`Un seul boxeur actif par carré ; hydratation entre les rounds et arrêt immédiat en cas de glissade.`},{id:9,slug:`deplacements-en-miroir-a-distance`,module:1,title:`Déplacements en miroir à distance`,level:`avancé`,durationMin:20,objective:`Lire les déplacements d’un partenaire placé à distance sans contact et maintenir l’écart constant en avançant, reculant, tournant.`,prerequisites:[`Changements de rythme en déplacement`,`Pivots sur l’appui avant`],organisation:{space:`Couloirs de 3 m de large, partenaires séparés par une bande neutre de 2 m matérialisée au sol`,material:[`Lignes de scotch de deux couleurs`,`Plots de limite`],groups:`Binômes meneur / suiveur, inversion toutes les 90 s`},schema:{kind:`cooperation`,phases:[`Meneur propose`,`Suiveur lit et copie`,`Écart de 2 m conservé`]},steps:[`Placement de part et d’autre de la bande neutre, gardes hautes, regard sur le buste du partenaire.`,`Le meneur avance ou recule de 1 à 3 pas ; le suiveur maintient l’écart (1 min 30, puis inversion).`,`Ajout des pas latéraux : le suiveur reproduit en miroir (meneur va à gauche, suiveur va à sa droite).`,`Le meneur ajoute un pivot ; le suiveur doit retrouver l’alignement face à face en un ou deux pas.`,`Round final : le meneur feinte un départ (épaule ou appui) sans bouger réellement ; le suiveur ne doit pas réagir aux feintes.`],decision:`Face à une amorce du meneur, le suiveur décide s’il s’agit d’un vrai déplacement à suivre ou d’une feinte à ignorer.`,corrections:[{error:`Le suiveur regarde les pieds et réagit en retard.`,fix:`Regarder le haut du buste du partenaire : les épaules et les hanches annoncent le déplacement.`},{error:`L’écart se réduit et la bande neutre est franchie.`,fix:`Rappel visuel : la bande colorée est infranchissable ; reculer d’abord, ajuster ensuite.`}],criteria:[`La bande neutre de 2 m n’est jamais franchie.`,`Le suiveur reproduit le déplacement avec moins d’une seconde de retard.`,`Le suiveur ignore au moins 2 feintes sur 3.`],adaptations:{enfants:`Jeu du « reflet dans l’eau » avec meneur adulte ; déplacements simples avant/arrière seulement.`,ados:`Le meneur compte les fois où il « décroche » le suiveur ; on inverse et on compare.`,jeunesAdultes:`Augmenter la vitesse et ajouter des changements de rythme imprévisibles, 3 rounds de 2 min.`},safety:`Distance minimale de 2 m obligatoire à tout moment ; aucun geste de frappe ni de contact, l’éducateur arrête le binôme si la bande est franchie.`},{id:10,slug:`circuit-appuis-et-garde`,module:1,title:`Circuit d’appuis et garde maintenue`,level:`avancé`,durationMin:25,objective:`Réinvestir toutes les acquisitions du module dans un parcours varié en conservant la qualité de garde, d’appuis et de directs dans le vide.`,prerequisites:[`Déplacements en miroir à distance`,`Direct du bras arrière et rotation du bassin`,`Changements de rythme en déplacement`],organisation:{space:`Parcours de 5 stations sur le pourtour de la salle, 3 m entre stations`,material:[`Cerceaux`,`Plots`,`Lignes au sol`,`Gommettes murales`,`Chronomètre`],groups:`Départs décalés de 30 s, un boxeur par station, observateurs aux stations 3 et 5`},schema:{kind:`deplacement`,phases:[`Stations d’appuis`,`Stations de directs dans le vide`,`Arrivée en garde`]},steps:[`Station 1 : 5 pas chassés avant/arrière dans un couloir, garde haute.`,`Station 2 : slalom latéral entre 4 plots sans croiser les jambes.`,`Station 3 : 4 pivots dans le cerceau puis 2 directs avant dans le vide vers une gommette.`,`Station 4 : 3 alternances direct avant / direct arrière dans le vide face au miroir.`,`Station 5 : changement de rythme (lent-vite-stop) puis arrêt final en garde 5 s ; 3 tours de circuit au total.`],decision:`À la station 5, le boxeur choisit l’enchaînement de rythme qui lui permet de s’arrêter exactement dans la zone finale marquée au sol.`,corrections:[{error:`La qualité se dégrade au fil des tours (garde basse, pieds serrés).`,fix:`Accepter de ralentir : la consigne est la propreté du geste, pas la vitesse du tour.`},{error:`Directs envoyés en marchant, sans base stable.`,fix:`S’arrêter en position avant chaque direct, puis lancer.`}],criteria:[`Les 5 stations sont réalisées sans croisement de jambes.`,`La garde est validée par l’observateur aux stations 3 et 5.`,`L’arrêt final dans la zone marquée est stable 5 s.`],adaptations:{enfants:`Circuit à 3 stations, présenté comme une « mission » avec un tampon par station réussie.`,ados:`Évaluation par les pairs avec une grille simple (oui / pas encore) sur les 3 critères.`,jeunesAdultes:`Circuit chronométré avec pénalités techniques ; objectif : garder la qualité sous fatigue légère.`},safety:`Départs décalés pour éviter les croisements ; gommettes à hauteur d’épaule, jamais de coup vers une personne ; pause et eau entre les tours.`}];var m=[{id:11,slug:`le-un-deux-dans-le-vide`,module:2,title:`Le « un-deux » dans le vide`,level:`découverte`,durationMin:15,objective:`Enchaîner direct avant puis direct arrière dans le vide sans pause, chaque poing revenant en garde avant le départ de l’autre.`,prerequisites:[`Direct du bras avant dans le vide`,`Direct du bras arrière et rotation du bassin`],organisation:{space:`Ligne face au miroir, 2 m entre boxeurs`,material:[`Miroir`,`Deux gommettes murales par boxeur (une par coup)`],groups:`Individuel, en ligne`},schema:{kind:`enchainement`,phases:[`Un : direct avant`,`Deux : direct arrière`,`Retour en garde`]},steps:[`Rappel des deux directs isolés au ralenti, 4 de chaque côté.`,`Compter « un… deux » avec 1 s entre les coups : le premier poing doit être revenu quand le second part (10 fois).`,`Réduire la pause : « un-deux » continu, retour en garde complet (3 séries de 8).`,`Viser alternativement les deux gommettes : un vers la gauche, deux vers la droite, sans quitter l’axe des épaules.`,`Au clap de l’éducateur, un « un-deux » ; deux claps, deux « un-deux » ; 15 appels variés.`],decision:`Selon le nombre de claps entendus, le boxeur choisit de lancer un ou deux enchaînements, et s’abstient si le clap est un faux départ annoncé.`,corrections:[{error:`Les deux poings sont dehors en même temps.`,fix:`Le premier poing « passe la main » au second : il doit toucher la pommette avant que l’autre parte.`},{error:`Le pied arrière ne pivote pas sur le deux.`,fix:`Revoir le travail du talon : sur « deux », le talon tourne avant le poing.`}],criteria:[`Le poing avant est revenu en garde avant le départ du direct arrière.`,`Le talon arrière pivote sur le deuxième coup.`,`Le boxeur reste équilibré sur ses appuis en fin d’enchaînement.`],adaptations:{enfants:`Chanson rythmée « un-deux, à la maison » pour garder le tempo ; séries de 5.`,ados:`Binôme observateur à 2 m qui signale par un pouce levé chaque enchaînement propre.`,jeunesAdultes:`Vitesse progressive sur 3 séries (lent, moyen, vif) en conservant la même qualité de retour.`},safety:`Travail dans le vide uniquement, coude jamais verrouillé ; 2 m d’écart latéral entre boxeurs.`},{id:12,slug:`un-deux-avec-pas-chasse`,module:2,title:`Un-deux avec pas chassé`,level:`découverte`,durationMin:15,objective:`Associer le « un-deux » à un pas chassé avant puis à un pas de sortie arrière, pour que les jambes et les bras travaillent ensemble.`,prerequisites:[`Le « un-deux » dans le vide`,`Pas chassé avant et arrière`],organisation:{space:`Couloirs de 5 m avec une ligne d’entrée et une ligne de sortie`,material:[`Lignes au sol`,`Plots aux extrémités`],groups:`Vagues de 4 boxeurs, 2 m de large par couloir`},schema:{kind:`deplacement`,phases:[`Entrée en pas chassé`,`Un-deux sur la ligne`,`Sortie arrière`]},steps:[`Pas chassé avant jusqu’à la ligne, arrêt, un-deux, arrêt (6 fois) : séparer d’abord les éléments.`,`Le direct avant part en même temps que le pied avant, le direct arrière suit en position (6 fois).`,`Ajouter la sortie : après le deux, pas chassé arrière jusqu’à la ligne de sortie.`,`Enchaîner trois fois entrée, un-deux, sortie dans le couloir, sans pause.`,`L’éducateur annonce « entre » ou « reste » : sur « reste », le boxeur fait un-deux sur place sans avancer (12 appels).`],decision:`Sur l’annonce, choisir entre entrer avec le pas chassé ou rester sur place, puis toujours sortir après l’enchaînement.`,corrections:[{error:`Le pied atterrit après le coup, le boxeur « tombe » sur son direct.`,fix:`Synchroniser : le pied avant et le poing avant arrivent ensemble.`},{error:`Le boxeur reste planté après le deux.`,fix:`Dire « deux… et sors ! » : la sortie fait partie de l’enchaînement.`}],criteria:[`Le direct avant et le pied avant arrivent ensemble.`,`La sortie arrière est systématique après le deux.`,`Les appuis restent écartés pendant l’entrée et la sortie.`],adaptations:{enfants:`Le couloir devient un « pont » : on entre, on fait un-deux au milieu, on recule vite avant qu’il se lève.`,ados:`Défi de propreté : 5 passages consécutifs sans erreur de synchronisation.`,jeunesAdultes:`Varier la longueur d’entrée (petit / grand pas chassé) selon une ligne de couleur annoncée.`},safety:`Vérifier la zone de recul avant chaque passage ; un seul boxeur par couloir.`},{id:13,slug:`crochet-avant-dans-le-vide`,module:2,title:`Crochet avant dans le vide`,level:`découverte`,durationMin:20,objective:`Découvrir le crochet du bras avant en trajectoire horizontale courte, avec rotation du pied avant, puis l’enchaîner après un direct.`,prerequisites:[`Le « un-deux » dans le vide`,`Pivots sur l’appui avant`],organisation:{space:`Face au miroir, 2 m entre boxeurs`,material:[`Miroir`,`Plot posé à 1 m devant chaque boxeur (repère de trajectoire au sol)`],groups:`Individuel puis binômes observateur/acteur`},schema:{kind:`enchainement`,phases:[`Coude à l’horizontale`,`Rotation pied et hanche avant`,`Retour en garde`]},steps:[`Sans frapper : lever le coude avant à l’horizontale, bras plié à 90°, puis le redescendre (8 fois).`,`Ajouter la rotation du pied avant (talon vers l’extérieur) et de la hanche ; le poing décrit un arc court au-dessus du plot (8 fois lents).`,`Crochet avant complet dans le vide, retour en garde par le même arc (3 séries de 6).`,`Enchaînement direct avant puis crochet avant, 8 fois, en restant sur place.`,`Enchaînement un-deux-crochet, 3 séries de 5, observé par le binôme à distance.`],decision:`Le binôme choisit d’annoncer « direct » ou « crochet » ; l’acteur doit adapter le premier coup à l’annonce sans hésitation.`,corrections:[{error:`Le bras s’ouvre largement comme un balayage.`,fix:`Garder l’angle de 90° au coude : le crochet est court et reste devant le corps.`},{error:`Rotation seulement du bras, pied avant figé.`,fix:`Le talon avant tourne en premier, la hanche entraîne l’épaule.`}],criteria:[`Coude à l’horizontale et angle proche de 90° en fin de geste.`,`Le pied avant pivote à chaque crochet.`,`La main arrière reste en garde.`],adaptations:{enfants:`Image de « la porte qui se ferme » ; uniquement crochet isolé et direct-crochet, séries de 4.`,ados:`Comparer au miroir l’arc du crochet avec un trait de scotch horizontal collé sur la vitre.`,jeunesAdultes:`Travail en vitesse modérée en cherchant le relâchement de l’épaule, 4 séries de 6.`},safety:`Amplitude réduite pour protéger l’épaule ; aucun partenaire dans l’arc du crochet (2 m de côté).`},{id:14,slug:`enchainement-direct-crochet-direct`,module:2,title:`Direct, crochet, direct`,level:`intermédiaire`,durationMin:20,objective:`Construire un enchaînement à trois coups en alternant les trajectoires droite, circulaire, droite, avec des transferts de poids fluides.`,prerequisites:[`Crochet avant dans le vide`,`Un-deux avec pas chassé`],organisation:{space:`Ligne face au miroir puis couloirs de 4 m`,material:[`Miroir`,`Lignes au sol`,`Fiches avec les numéros des coups`],groups:`Individuel, puis petits groupes de 3 avec un lecteur de fiche`},schema:{kind:`enchainement`,phases:[`Direct avant`,`Crochet avant`,`Direct arrière`]},steps:[`Rappel du code chiffré : 1 = direct avant, 2 = direct arrière, 3 = crochet avant.`,`Enchaînement 1-3-2 au ralenti, pause d’1 s entre chaque coup (8 fois).`,`Supprimer les pauses en gardant les retours en garde (3 séries de 6).`,`Ajouter un pas latéral de sortie après le 2 (6 fois de chaque côté).`,`Le lecteur annonce au hasard 1-2, 1-3 ou 1-3-2 ; l’acteur réalise l’enchaînement demandé (12 appels, rotation des rôles).`],decision:`Le boxeur choisit le côté de la sortie latérale après le 1-3-2 en fonction d’un plot placé à sa gauche ou à sa droite par l’éducateur.`,corrections:[{error:`Le poids reste sur la jambe avant après le crochet, le direct arrière manque d’appui.`,fix:`Le crochet ramène le poids au centre, ce qui « charge » le direct arrière.`},{error:`Enchaînement saccadé, avec des arrêts entre les coups.`,fix:`Chaque coup prépare le suivant : penser à la rotation qui s’inverse, comme une essoreuse.`}],criteria:[`Les trois coups sont distincts et reconnaissables.`,`Aucune perte d’équilibre sur la sortie latérale.`,`Le bon enchaînement est réalisé dans au moins 10 appels sur 12.`],adaptations:{enfants:`Code couleur au lieu des chiffres (rouge, bleu, jaune) ; enchaînements à 2 coups seulement.`,ados:`Créer son propre code et le faire réaliser à un camarade.`,jeunesAdultes:`Enchaînement sur 1 min en continu, puis 30 s de repos, 3 séries, qualité contrôlée au miroir.`},safety:`Groupes de 3 espacés de 3 m ; le lecteur reste à 2 m de l’acteur, jamais dans l’axe des coups.`},{id:15,slug:`uppercut-arriere-dans-le-vide`,module:2,title:`Uppercut arrière dans le vide`,level:`intermédiaire`,durationMin:20,objective:`Apprendre l’uppercut du bras arrière en trajectoire verticale courte, porté par une légère flexion-extension des jambes, sans se découvrir.`,prerequisites:[`Direct du bras arrière et rotation du bassin`,`Crochet avant dans le vide`],organisation:{space:`Face au miroir, 2 m entre boxeurs`,material:[`Miroir`,`Ligne verticale de scotch sur le miroir (axe de trajectoire)`],groups:`Individuel puis binômes observateur/acteur`},schema:{kind:`appuis`,phases:[`Fléchir légèrement`,`Pousser et tourner la hanche`,`Retour en garde`]},steps:[`Flexion légère des genoux puis extension avec rotation de la hanche arrière, sans les bras (10 fois).`,`Ajouter le bras : coude près du corps, poing qui monte le long de la ligne verticale, paume vers soi (8 fois lents).`,`Uppercut complet et retour immédiat en garde, 3 séries de 6.`,`Enchaîner direct avant puis uppercut arrière (1-6), 8 fois.`,`Le binôme annonce « haut » (direct arrière) ou « bas » (uppercut arrière) : l’acteur répond par le coup adapté (12 appels).`],decision:`Sur l’annonce « haut » ou « bas », choisir le coup arrière adapté en conservant la même préparation des appuis.`,corrections:[{error:`Le bras descend pour prendre de l’élan avant de monter.`,fix:`Pas de « pelle » : le poing part de la garde, l’impulsion vient des jambes.`},{error:`Le menton se relève pendant l’uppercut.`,fix:`Regarder le poing à travers la garde, menton rentré.`}],criteria:[`Le poing part directement de la garde, sans armé vers le bas.`,`Flexion-extension des jambes visible à chaque uppercut.`,`La main avant reste en garde.`],adaptations:{enfants:`Image de « la fusée qui décolle » depuis les genoux ; séries de 4 avec pause.`,ados:`Travail filmé au ralenti (avec accord) pour vérifier l’absence d’armé.`,jeunesAdultes:`Enchaînements 1-6-3 à vitesse moyenne, 3 séries de 6, en cherchant la fluidité des rotations.`},safety:`Flexions modérées, dos droit ; aucun coup dirigé vers le partenaire, qui reste à 2 m sur le côté.`},{id:16,slug:`enchainements-de-trois-a-quatre-coups`,module:2,title:`Enchaînements de trois à quatre coups`,level:`intermédiaire`,durationMin:20,objective:`Réaliser des séries de 3 à 4 coups variés dans le vide en gardant rythme, équilibre et retours en garde, puis sortir de l’axe.`,prerequisites:[`Direct, crochet, direct`,`Uppercut arrière dans le vide`],organisation:{space:`Un cerceau au sol par boxeur (zone d’appuis), 3 m entre cerceaux`,material:[`Cerceaux`,`Cartes d’enchaînements (4 cartes par groupe)`,`Chronomètre`],groups:`Groupes de 3 : un acteur, un lecteur de carte, un observateur, rotation toutes les 2 min`},schema:{kind:`enchainement`,phases:[`Lecture de la carte`,`Série de 3–4 coups`,`Sortie hors du cerceau`]},steps:[`Découverte des 4 cartes : 1-2-3, 1-6-3, 1-2-3-2, 1-1-2 ; démonstration au ralenti de chacune.`,`Chaque carte réalisée 4 fois lentement, pied avant dans le cerceau.`,`Réalisation à vitesse moyenne avec sortie latérale hors du cerceau après la série.`,`Le lecteur tire une carte au hasard, l’acteur exécute ; 2 min par acteur.`,`L’observateur donne un seul conseil à la fin, puis rotation des rôles.`],decision:`Après chaque série, l’acteur choisit le côté de sortie selon le dernier coup réalisé (sortie côté opposé à la main qui vient de partir).`,corrections:[{error:`Le dernier coup est bâclé, le boxeur se relâche trop tôt.`,fix:`Compter le dernier coup à voix haute et finir en garde avant de sortir.`},{error:`Les pieds sortent du cerceau pendant la série.`,fix:`Raccourcir les rotations : la série se fait sur place, la sortie vient après.`}],criteria:[`Les 4 cartes sont réalisées sans erreur de coup.`,`Retour en garde visible entre chaque coup.`,`Sortie systématique et équilibrée après la série.`],adaptations:{enfants:`Cartes illustrées avec 2 ou 3 coups maximum ; l’observateur colle une gommette « bravo » sur la carte réussie.`,ados:`Inventer une cinquième carte et la soumettre au groupe.`,jeunesAdultes:`Lecture de carte plus rapide (toutes les 4 s) pour travailler l’enchaînement sous pression de temps.`},safety:`Lecteur et observateur à 2 m minimum de l’acteur, hors de l’axe des coups ; pause eau à chaque rotation.`},{id:17,slug:`enchainer-en-se-deplacant-sur-un-angle`,module:2,title:`Enchaîner en se déplaçant sur un angle`,level:`avancé`,durationMin:20,objective:`Placer un enchaînement puis changer d’angle par pivot ou pas latéral pour enchaîner de nouveau face à une nouvelle direction.`,prerequisites:[`Enchaînements de trois à quatre coups`,`Pivots sur l’appui avant`],organisation:{space:`Croix au sol de 4 m de branche, un repère de couleur au bout de chaque branche`,material:[`Lignes au sol`,`Plots de 4 couleurs`],groups:`Un boxeur au centre de chaque croix, binôme observateur à 2 m`},schema:{kind:`deplacement`,phases:[`Enchaînement face au repère`,`Pivot ou pas latéral`,`Nouvel enchaînement`]},steps:[`Face au plot rouge : 1-2 dans le vide, pivot d’un quart de tour vers le plot bleu, 1-2 (4 tours de croix).`,`Même travail avec pas latéral au lieu du pivot (4 tours).`,`Enchaînement 1-2-3 puis pivot, 1-2-3 puis pas latéral, en alternant.`,`L’observateur annonce une couleur : l’acteur s’oriente vers ce plot par le moyen le plus rapide et enchaîne 1-2.`,`Round de 1 min 30 : l’acteur choisit librement ses changements d’angle et ses enchaînements, l’observateur compte les fins de série équilibrées.`],decision:`Sur la couleur annoncée, choisir entre pivot et pas latéral selon la position du plot par rapport au pied avant.`,corrections:[{error:`Le pivot démarre avant la fin du dernier coup, garde ouverte.`,fix:`Coup terminé, garde reprise, puis seulement pivot.`},{error:`Après le changement d’angle, le boxeur n’est pas aligné face au repère.`,fix:`Vérifier l’alignement nez-plot avant de relancer les coups.`}],criteria:[`Le boxeur fait face au bon repère avant chaque nouvel enchaînement.`,`Aucun coup lancé pendant le pivot.`,`Au moins 6 fins de série équilibrées en 1 min 30.`],adaptations:{enfants:`Seulement deux branches (rouge et bleu) et des enchaînements de 2 coups ; jeu de la « boussole ».`,ados:`Défi à deux croix voisines : les deux boxeurs doivent pivoter en même temps sur l’annonce, sans se regarder.`,jeunesAdultes:`Enchaînements de 4 coups et changements d’angle en moins d’1 s, 3 rounds de 1 min 30.`},safety:`Croix espacées de 4 m entre elles ; l’observateur se place hors des branches, jamais face à un plot actif.`},{id:18,slug:`enchainements-et-changement-de-rythme`,module:2,title:`Enchaînements et changement de rythme`,level:`avancé`,durationMin:20,objective:`Varier le tempo à l’intérieur d’un même enchaînement (lent-vif, vif-lent, pause) pour apprendre à le rendre imprévisible.`,prerequisites:[`Enchaînements de trois à quatre coups`,`Changements de rythme en déplacement`],organisation:{space:`Ligne face au miroir puis espace libre, 2 m autour de chaque boxeur`,material:[`Miroir`,`Métronome ou musique à tempo variable`],groups:`Individuel puis binômes en miroir à distance (sans contact)`},schema:{kind:`enchainement`,phases:[`Tempo lent`,`Rupture vive`,`Retour au calme en garde`]},steps:[`1-2-3 au tempo régulier du métronome, 6 fois.`,`Même enchaînement en « lent-lent-vif » : les deux premiers coups calmes, le troisième vif (8 fois).`,`Inverser en « vif-vif-lent », puis ajouter une pause d’1 s avant le dernier coup (8 fois chacun).`,`En binôme à 2 m : l’un réalise son enchaînement, l’autre doit deviner et frapper des mains au moment de la rupture.`,`Round libre de 1 min 30 en déplacement : le boxeur combine enchaînements et ruptures de son choix.`],decision:`Pendant le round libre, choisir à quel coup placer la rupture de rythme pour qu’elle soit la moins prévisible pour l’observateur.`,corrections:[{error:`La rupture vive fait perdre la garde et l’équilibre.`,fix:`La vitesse vient du relâchement : expirer sur le coup vif, épaules souples.`},{error:`Le tempo reste uniforme malgré la consigne.`,fix:`Exagérer d’abord le contraste (très lent / vif), puis l’affiner.`}],criteria:[`Le contraste de tempo est clairement visible par l’observateur.`,`L’équilibre est conservé après le coup vif.`,`L’observateur rate au moins une rupture sur trois lors de l’exercice en binôme.`],adaptations:{enfants:`Jeu de « l’escargot et l’éclair » sur 2 coups, avec des images de tempo.`,ados:`Battle de rythme à distance, jugée par le groupe sur la créativité et la propreté.`,jeunesAdultes:`Travail sur musique à tempo changeant, 3 rounds de 2 min avec 45 s de récupération.`},safety:`Binômes à 2 m minimum, coups dirigés dans le vide et jamais vers le partenaire ; hydratation entre rounds.`},{id:19,slug:`shadow-boxing-construit`,module:2,title:`Shadow-boxing construit`,level:`avancé`,durationMin:25,objective:`Construire un shadow-boxing structuré de 2 minutes alternant déplacements, enchaînements, changements d’angle et retours en garde, sans adversaire réel.`,prerequisites:[`Enchaîner en se déplaçant sur un angle`,`Enchaînements et changement de rythme`],organisation:{space:`Zone personnelle de 3 m × 3 m marquée au sol pour chaque boxeur`,material:[`Plots aux angles`,`Fiche de plan de round`,`Chronomètre ou minuterie de rounds`],groups:`Individuel, avec un observateur pour deux boxeurs`},schema:{kind:`distance`,phases:[`Préparer son plan`,`Round de shadow`,`Bilan avec l’observateur`]},steps:[`Chaque boxeur écrit son plan de round : 3 enchaînements favoris, 2 changements d’angle, 1 rupture de rythme.`,`Round 1 (1 min 30) au ralenti en suivant le plan, sans sortir de sa zone.`,`Round 2 (2 min) à vitesse moyenne ; l’observateur coche sur la fiche les éléments réalisés.`,`Bilan de 1 min : l’observateur indique un point fort et un point à travailler.`,`Round 3 (2 min) en intégrant la correction, puis étirements légers des épaules.`],decision:`Pendant le round, le boxeur choisit dans son plan l’enchaînement suivant en fonction de sa position dans la zone (près d’un bord : enchaînement plus sortie vers le centre).`,corrections:[{error:`Le shadow se résume à une suite de coups sans déplacement.`,fix:`Règle : après chaque enchaînement, au moins deux pas ou un pivot.`},{error:`Le boxeur sort de sa zone ou s’arrête de bouger.`,fix:`Utiliser les plots d’angle comme repères pour revenir vers le centre.`}],criteria:[`Tous les éléments du plan sont cochés par l’observateur au round 2.`,`Le boxeur reste dans sa zone pendant tout le round.`,`La correction donnée au bilan est visible au round 3.`],adaptations:{enfants:`Plan illustré en 3 cases et rounds de 1 min ; l’éducateur guide à voix haute.`,ados:`Le plan est écrit à deux et mélange les enchaînements favoris des deux boxeurs.`,jeunesAdultes:`3 rounds de 2 min avec 1 min de repos, plan modifié à chaque round selon le retour.`},safety:`Zones séparées d’au moins 1 m ; aucune cible humaine, l’observateur reste en dehors des zones ; échauffement préalable des épaules.`},{id:20,slug:`enchainements-cooperatifs-en-miroir`,module:2,title:`Enchaînements coopératifs en miroir`,level:`avancé`,durationMin:25,objective:`Proposer et reproduire des enchaînements avec un partenaire placé à distance, sans contact, pour développer lecture, mémoire et synchronisation.`,prerequisites:[`Shadow-boxing construit`,`Déplacements en miroir à distance`],organisation:{space:`Binômes face à face de part et d’autre d’une bande neutre de 2,5 m au sol`,material:[`Lignes de scotch de couleur`,`Plots de limite`,`Chronomètre`],groups:`Binômes meneur / suiveur, inversion toutes les 2 min`},schema:{kind:`cooperation`,phases:[`Le meneur montre`,`Le suiveur reproduit`,`Synchronisation finale`]},steps:[`Le meneur réalise un enchaînement de 2 coups dans le vide, le suiveur le reproduit juste après (10 propositions).`,`Passage à 3 coups avec un déplacement inclus (pas chassé ou pivot), toujours sans franchir la bande.`,`Le suiveur reproduit en miroir : direct avant du meneur = direct avant du suiveur, même côté apparent.`,`Synchronisation : les deux réalisent le même enchaînement en même temps, au compte du meneur (8 fois).`,`Le meneur propose un enchaînement, le suiveur répond par un enchaînement différent qui finit par une sortie latérale (2 min, puis inversion).`],decision:`À l’étape 5, le suiveur choisit son enchaînement de réponse et le côté de sortie selon celui proposé par le meneur.`,corrections:[{error:`Les partenaires se rapprochent et franchissent la bande.`,fix:`Arrêt immédiat, reculer derrière sa ligne : la bande neutre est la règle numéro un.`},{error:`Le suiveur reproduit un enchaînement différent faute d’attention.`,fix:`Le meneur ralentit et nomme les coups à voix haute jusqu’à ce que la lecture soit fiable.`}],criteria:[`La bande neutre de 2,5 m n’est jamais franchie.`,`Le suiveur reproduit correctement 8 enchaînements sur 10.`,`Les deux partenaires terminent la synchronisation en même temps.`],adaptations:{enfants:`Meneur adulte ou éducateur, enchaînements de 2 coups, jeu du « perroquet boxeur ».`,ados:`Points de coopération : le binôme gagne un point par synchronisation parfaite, objectif commun annoncé au départ.`,jeunesAdultes:`Enchaînements de 4 coups avec changement de rythme, réponse en moins de 2 s.`},safety:`Distance de 2,5 m obligatoire et matérialisée ; aucun coup vers la tête ou le corps du partenaire, uniquement dans le vide à côté de l’axe ; l’éducateur supervise chaque binôme.`}];var v=[{id:21,slug:`garde-haute-et-couverture`,module:3,title:`Garde haute et couverture`,level:`découverte`,durationMin:15,objective:`Installer une garde protectrice stable : poings à hauteur des pommettes, coudes serrés, menton rentré. Savoir la retrouver instantanément après chaque geste.`,prerequisites:[`Garde de base et position des appuis`,`Pas chassés avant/arrière`],organisation:{space:`Salle libre ou ring, un mètre carré par boxeur, face aux miroirs si possible.`,material:[`Miroir mural`,`Foulards de couleur`,`Chronomètre`],groups:`Travail individuel au miroir, puis binômes observateur/boxeur.`},schema:{kind:`defense`,phases:[`Garde vérifiée au miroir`,`Couverture sur signal`,`Retour en garde`]},steps:[`Au miroir, prendre la garde : vérifier poings aux pommettes, coudes devant les côtes, menton rentré (3 x 20 s, relâcher entre chaque).`,`Se déplacer en pas chassés (avant, arrière, côtés) pendant 30 s sans que la garde ne descende ; le partenaire signale toute main qui tombe.`,`Sur un foulard levé par le partenaire, resserrer la garde en couverture (avant-bras collés, regard entre les gants) puis relâcher en garde normale (10 répétitions).`,`Enchaîner un direct du bras avant dans le vide puis revenir en garde complète avant le signal suivant (2 x 8).`,`Round de 1 min : déplacements libres, le partenaire lève le foulard au hasard ; on vérifie la couverture en moins d’une seconde.`],decision:`Le partenaire montre un foulard rouge (couverture complète) ou bleu (garder la garde et continuer à bouger) : le boxeur choisit la bonne réponse sans s’arrêter de se déplacer.`,corrections:[{error:`Coudes écartés qui ouvrent les flancs.`,fix:`Imaginer serrer une feuille de papier entre coude et côtes.`},{error:`Menton levé, regard au plafond en couverture.`,fix:`Regarder le partenaire « par-dessus les gants », menton vers la poitrine.`},{error:`Main arrière qui tombe après le direct.`,fix:`Laisser la main arrière « collée » à la joue pendant tout le geste.`}],criteria:[`Les poings restent au-dessus des épaules pendant 30 s de déplacement.`,`La couverture est prise en moins d’une seconde après le signal.`,`Le menton reste rentré pendant tout le round.`],adaptations:{enfants:`Jeu de la « maison fermée » : au signal, on ferme portes (avant-bras) et fenêtres (gants) ; signaux très visibles, durées de 20 s.`,ados:`Défi en binôme : l’observateur compte les mains qui tombent, objectif zéro sur le round ; on inverse les rôles.`,jeunesAdultes:`Ajouter la respiration (expirer à la couverture) et allonger les rounds à 2 min avec signaux plus rapprochés.`},safety:`Aucun geste du partenaire vers le visage : seuls les foulards servent de signal, tenus à bout de bras et à plus de deux mètres.`},{id:22,slug:`esquive-rotative-du-buste`,module:3,title:`Esquive rotative du buste`,level:`découverte`,durationMin:15,objective:`Sortir la tête de l’axe par une rotation du buste et des hanches, sans perdre les appuis ni la garde.`,prerequisites:[`Garde haute et couverture`,`Coordination hanches-épaules`],organisation:{space:`Ligne au sol (ruban adhésif), un boxeur par ligne, deux mètres entre les lignes.`,material:[`Ruban adhésif au sol`,`Balles en mousse`,`Miroir`],groups:`Binômes : un lanceur de signal, un boxeur ; rotation toutes les 2 min.`},schema:{kind:`defense`,phases:[`Tête dans l’axe`,`Rotation hors de la ligne`,`Retour garde centrée`]},steps:[`Pieds de part et d’autre de la ligne au sol : faire passer la tête de l’autre côté de la ligne par rotation des hanches, lentement (10 de chaque côté).`,`Au miroir, vérifier que l’épaule avant monte légèrement et que le regard reste sur le miroir (2 x 10).`,`Le partenaire, à trois mètres, tend lentement la main gauche ou droite comme signal : esquive du côté opposé (15 répétitions).`,`Esquive puis retour en garde centrée, en comptant à voix haute « un-deux » pour le rythme (2 x 10).`,`Le partenaire lève une balle en mousse à droite ou à gauche au hasard : le boxeur esquive du bon côté et revient (1 min).`],decision:`Selon le côté où la balle est levée, le boxeur choisit l’esquive extérieure ou intérieure ; si le partenaire lève les deux balles, il recule d’un pas au lieu d’esquiver.`,corrections:[{error:`Le boxeur se penche en avant en cassant la taille.`,fix:`Garder le buste droit et tourner autour d’une colonne imaginaire.`},{error:`Talons qui décollent et perte d’équilibre.`,fix:`Pivoter sur l’avant du pied, genoux souples, poids réparti.`}],criteria:[`La tête franchit la ligne au sol sans que les pieds bougent.`,`Le regard reste orienté vers le partenaire pendant l’esquive.`,`Le retour en garde est complet avant le signal suivant.`],adaptations:{enfants:`Jeu du « tunnel » : passer la tête d’une rive à l’autre de la rivière (ligne) ; signaux annoncés à la voix avant d’être visuels.`,ados:`Augmenter la fréquence des signaux et mesurer le nombre d’esquives correctes sur 30 s.`,jeunesAdultes:`Lier l’esquive à un direct dans le vide du côté libéré, en gardant la rotation comme source de puissance.`},safety:`Le partenaire reste à trois mètres et ne s’avance jamais ; mouvements de rotation sans à-coup pour protéger le bas du dos.`},{id:23,slug:`retrait-du-buste`,module:3,title:`Retrait du buste`,level:`découverte`,durationMin:12,objective:`Éloigner la tête d’un direct annoncé en transférant le poids sur la jambe arrière, puis revenir en position de remise.`,prerequisites:[`Garde haute et couverture`,`Transfert du poids avant-arrière`],organisation:{space:`Couloirs de trois mètres, boxeurs face à face à distance de sécurité marquée par deux plots.`,material:[`Plots`,`Miroir`,`Chronomètre`],groups:`Binômes, rôles inversés à chaque série.`},schema:{kind:`defense`,phases:[`Poids au centre`,`Bascule sur l’arrière`,`Retour en appui`]},steps:[`Sans partenaire, basculer le poids sur la jambe arrière en gardant les pieds fixes : la tête recule d’une vingtaine de centimètres (2 x 10).`,`Au miroir, contrôler que les gants restent devant le visage et que le menton ne monte pas (2 x 8).`,`Le partenaire, derrière son plot, mime lentement un direct dans le vide : le boxeur recule le buste au moment où le bras se tend (12 répétitions).`,`Après le retrait, revenir sur l’appui avant en lançant un direct du bras arrière dans le vide (2 x 8).`,`Alterner sur signal vocal « retrait » ou « pas arrière » pour différencier les deux solutions (1 min).`],decision:`Si le partenaire mime un seul direct, retrait du buste ; s’il annonce « double », le boxeur doit choisir un pas arrière complet car le retrait seul ne suffit plus.`,corrections:[{error:`Le boxeur recule en se cambrant fortement.`,fix:`Fléchir la jambe arrière : c’est le genou qui absorbe, pas le dos.`},{error:`Les mains suivent la tête et s’écartent.`,fix:`Garder les gants à la même distance du visage pendant le retrait.`}],criteria:[`Les pieds restent fixes pendant le retrait.`,`Le retour en appui avant est fluide, sans temps mort.`,`Le choix retrait / pas arrière correspond au signal dans 8 cas sur 10.`],adaptations:{enfants:`Image du « roseau qui plie » ; seulement le retrait sans remise, partenaire qui mime très lentement.`,ados:`Introduire la remise immédiate et compter les retours corrects en 30 s.`,jeunesAdultes:`Varier le rythme du mime (lent, moyen) et travailler le retrait en enchaînement de déplacements.`},safety:`Le partenaire mime derrière son plot, bras tendu à plus d’un mètre du visage du boxeur ; aucun mouvement brusque du dos.`},{id:24,slug:`parade-chassee-du-direct`,module:3,title:`Parade chassée du direct`,level:`intermédiaire`,durationMin:18,objective:`Dévier latéralement un direct annoncé par un petit mouvement de la main arrière, sans aller chercher le coup ni ouvrir la garde.`,prerequisites:[`Garde haute et couverture`,`Enchaînements du direct`],organisation:{space:`Binômes face à face sur une ligne, distance de bras tendu plus un pas, marquée au sol.`,material:[`Marques au sol`,`Foulards`,`Miroir`],groups:`Binômes de gabarit proche, un attaquant mime et un défenseur.`},schema:{kind:`defense`,phases:[`Direct mimé à distance`,`Paume qui chasse`,`Main revenue à la joue`]},steps:[`Au miroir, petit geste de la paume arrière vers l’intérieur, amplitude d’une main, retour immédiat à la joue (2 x 15).`,`Le partenaire tient un foulard tendu à bout de bras, immobile : le défenseur effleure le foulard du bout du gant et revient (10 répétitions).`,`Le partenaire mime un direct lent et annoncé à voix haute, hors de portée : parade dans le vide au bon moment (2 x 10).`,`Parade suivie d’un direct du bras avant dans le vide (2 x 8).`,`Le partenaire annonce « direct » ou « rien » au dernier moment : le défenseur ne pare que s’il y a un direct (1 min).`],decision:`Face à un direct du bras avant, choisir entre parade chassée (on reste sur place pour remiser) et retrait du buste (on préfère s’éloigner) selon la consigne « rester » ou « sortir ».`,corrections:[{error:`La main part loin à la rencontre du coup.`,fix:`Le mouvement reste devant le visage, amplitude maximale de la largeur d’un gant.`},{error:`Les deux mains bougent ensemble.`,fix:`La main avant reste en place, prête à remiser.`},{error:`Parade anticipée avant le geste du partenaire.`,fix:`Attendre le départ de l’épaule du partenaire avant de réagir.`}],criteria:[`Le gant de parade revient à la joue en moins d’une seconde.`,`La main avant ne bouge pas pendant la parade.`,`Aucune parade sur l’annonce « rien ».`],adaptations:{enfants:`Jeu « chasser la mouche » avec le foulard immobile ; pas de mime de coup, uniquement des cibles fixes.`,ados:`Ajouter la remise et un comptage des réponses justes ; rotation des binômes toutes les 2 min.`,jeunesAdultes:`Travailler la parade des deux côtés (main avant sur direct arrière mimé) et varier le rythme des annonces.`},safety:`Le mime se fait à distance marquée, jamais à portée : le défenseur pare le vide, aucun gant ne doit se toucher en dehors du foulard immobile.`},{id:25,slug:`blocage-du-crochet-annonce`,module:3,title:`Blocage haut contre crochet annoncé`,level:`intermédiaire`,durationMin:15,objective:`Protéger le côté de la tête en montant l’avant-bras et le gant contre la tempe sur un crochet mimé, puis rester stable pour enchaîner.`,prerequisites:[`Garde haute et couverture`,`Crochet dans le vide`],organisation:{space:`Ring ou salle, binômes espacés de trois mètres, plots matérialisant la distance de sécurité.`,material:[`Plots`,`Foulards bicolores`,`Chronomètre`],groups:`Binômes ; l’entraîneur passe pour vérifier les coudes.`},schema:{kind:`defense`,phases:[`Signal côté gauche ou droit`,`Gant à la tempe, coude bas`,`Remise croisée dans le vide`]},steps:[`Seul, monter alternativement chaque gant contre la tempe, coude pointé vers le bas, avant-bras vertical (2 x 10 par côté).`,`Ajouter une légère flexion des jambes du côté du blocage pour absorber (2 x 8).`,`Le partenaire mime un crochet lent derrière son plot en annonçant le côté : blocage du côté correspondant (2 x 10).`,`Blocage puis crochet du bras opposé dans le vide (2 x 8).`,`Le partenaire lève un foulard à gauche ou à droite sans annoncer : blocage du bon côté, puis remise (1 min 30).`],decision:`Si le foulard est levé haut, blocage ; s’il est levé bas, esquive rotative à la place : le boxeur choisit la défense adaptée au signal.`,corrections:[{error:`Le coude monte et ouvre le flanc.`,fix:`Le coude descend vers la hanche, seul le gant monte.`},{error:`Le boxeur tourne la tête vers le côté bloqué.`,fix:`Garder le regard droit devant, vers le partenaire.`}],criteria:[`L’avant-bras est vertical et le coude bas au moment du blocage.`,`Le côté du blocage correspond au signal dans 9 cas sur 10.`,`La remise part sans que le gant de blocage ne quitte la tempe.`],adaptations:{enfants:`Image du « téléphone » : on décroche le combiné à l’oreille ; un seul côté à la fois, signaux annoncés.`,ados:`Alterner blocage et esquive selon la hauteur du foulard, en défi de rapidité.`,jeunesAdultes:`Enchaîner deux blocages successifs (gauche-droite) avant la remise, rounds de 2 min.`},safety:`Le partenaire mime toujours derrière son plot ; le blocage se fait sans contact, aucun bras ne vient toucher le gant du défenseur.`},{id:26,slug:`esquive-basse-par-flexion`,module:3,title:`Esquive basse par flexion`,level:`intermédiaire`,durationMin:15,objective:`Passer sous une trajectoire haute en fléchissant les jambes, dos droit et regard vers l’avant, puis remonter en garde équilibrée.`,prerequisites:[`Esquive rotative du buste`,`Garde haute et couverture`],organisation:{space:`Salle libre, binômes à trois mètres ; un élastique tendu entre deux plots hauts pour certains ateliers.`,material:[`Élastique ou corde légère`,`Deux plots hauts`,`Balles en mousse`],groups:`Petits groupes de trois : deux tiennent l’élastique, un passe dessous.`},schema:{kind:`defense`,phases:[`Garde haute`,`Flexion sous la ligne`,`Remontée en garde`]},steps:[`Flexions lentes dos droit, regard devant : descendre de vingt centimètres et remonter (2 x 10).`,`Passer sous l’élastique fixe tenu à hauteur d’épaule, sans le toucher (12 passages).`,`Le partenaire fait balayer lentement l’élastique de gauche à droite à distance : flexion au bon moment (2 x 8).`,`Flexion puis uppercut dans le vide en remontant (2 x 8).`,`Le partenaire lève une balle haute (flexion) ou basse (rester debout et couvrir) : choix en 1 min.`],decision:`Balle haute : flexion ; balle à hauteur de buste : couverture debout, car se baisser exposerait la tête : le boxeur doit choisir sans hésiter.`,corrections:[{error:`Le boxeur plonge la tête en avant en se penchant.`,fix:`Descendre comme sur une chaise : ce sont les genoux qui plient.`},{error:`Regard vers le sol pendant la flexion.`,fix:`Fixer la poitrine du partenaire tout au long du mouvement.`}],criteria:[`Le dos reste droit pendant la flexion.`,`Les gants restent en garde en position basse.`,`L’élastique n’est jamais touché sur 10 passages.`],adaptations:{enfants:`Jeu du « limbo boxe » avec l’élastique fixe et assez haut ; pas de balayage.`,ados:`Élastique en mouvement lent et ajout de l’uppercut en remontée.`,jeunesAdultes:`Combiner flexion et pas latéral pour sortir de l’axe en remontant.`},safety:`L’élastique est léger et tenu sans tension par des partenaires attentifs, toujours à hauteur d’épaule ou plus ; flexions limitées en amplitude pour protéger les genoux.`},{id:27,slug:`rouler-sous-le-crochet`,module:3,title:`Rouler sous le crochet`,level:`intermédiaire`,durationMin:20,objective:`Enchaîner flexion et déplacement latéral du buste en « U » pour passer sous une trajectoire circulaire mimée et ressortir de l’autre côté, prêt à remiser.`,prerequisites:[`Esquive basse par flexion`,`Esquive rotative du buste`],organisation:{space:`Couloirs de quatre mètres, plots au sol formant un U de repère pour la tête.`,material:[`Plots`,`Élastique léger`,`Miroir`],groups:`Groupes de trois pour tenir l’élastique, puis binômes.`},schema:{kind:`defense`,phases:[`Départ côté gauche`,`Passage bas en U`,`Sortie côté droit`]},steps:[`Au miroir, dessiner un U avec la tête en fléchissant puis en se relevant de l’autre côté, très lentement (2 x 8).`,`Passer sous l’élastique tenu en diagonale (de l’épaule à la hanche opposée) en suivant le U (2 x 8).`,`Le partenaire mime lentement un crochet large derrière son plot : rouler dans le sens opposé à la trajectoire (2 x 10).`,`Rouler puis crochet dans le vide du côté de sortie (2 x 8).`,`Le partenaire annonce « crochet gauche », « crochet droit » ou « direct » : rouler sur les crochets, parer ou retirer sur le direct (1 min 30).`],decision:`Sur crochet, rouler sous ; sur direct, rouler serait trop lent : le boxeur choisit une parade ou un retrait. Il distingue les deux trajectoires annoncées.`,corrections:[{error:`Le boxeur descend et remonte du même côté.`,fix:`Penser à « entrer d’un côté de la cuvette et sortir de l’autre ».`},{error:`Les gants descendent avec le buste.`,fix:`Les gants restent collés au visage durant tout le U.`},{error:`Les pieds se croisent pendant le mouvement.`,fix:`Pieds fixes au départ, puis petit pas latéral seulement à la sortie.`}],criteria:[`La tête trace un U complet sans s’arrêter au point bas.`,`Le boxeur sort du côté opposé à la trajectoire mimée.`,`La remise part depuis une garde stable.`],adaptations:{enfants:`Version « passer sous le pont » avec élastique fixe, sans mime de coup, et images de mouvement de bateau.`,ados:`Mime de crochet lent et annonce du côté ; comptage des sorties du bon côté.`,jeunesAdultes:`Enchaîner deux roulés successifs puis remise en deux coups dans le vide.`},safety:`Flexion modérée, genoux dans l’axe des pieds ; le partenaire mime derrière son plot, sans aucune approche, et l’élastique est lâché au moindre accrochage.`},{id:28,slug:`sortir-de-l-axe-pas-lateral`,module:3,title:`Sortir de l’axe par pas latéral`,level:`avancé`,durationMin:18,objective:`Combiner défense et déplacement : après un geste défensif, quitter la ligne d’attaque par un pas latéral ou un pivot pour se replacer en angle.`,prerequisites:[`Parade chassée du direct`,`Pas chassés latéraux`,`Pivot sur le pied avant`],organisation:{space:`Carré de quatre mètres matérialisé par des plots, une ligne centrale au sol représentant l’axe d’attaque.`,material:[`Plots`,`Ruban adhésif`,`Foulards bicolores`],groups:`Binômes, rôle de signaleur et de boxeur.`},schema:{kind:`deplacement`,phases:[`Sur la ligne d’attaque`,`Défense + pas latéral`,`Garde en angle`]},steps:[`Sur la ligne au sol, pas latéral vers l’extérieur du pied avant puis retour en garde, sans croiser (2 x 10).`,`Pivot sur le pied avant d’un quart de tour pour se retrouver hors de la ligne (2 x 8 par côté).`,`Parade dans le vide puis pas latéral immédiat sur un signal du partenaire (2 x 8).`,`Le partenaire, placé à trois mètres, avance d’un pas lent : le boxeur sort de l’axe et se retrouve de profil par rapport à sa trajectoire (2 x 8).`,`Round de 1 min 30 : foulard rouge = pas latéral à gauche, bleu = pivot, les deux = pas arrière.`],decision:`Quand le partenaire avance en ligne droite, le boxeur choisit entre pas latéral (l’espace est libre sur le côté) et pivot (il est proche d’un plot qui figure les cordes).`,corrections:[{error:`Pas latéral sur le côté qui rapproche de la main arrière du partenaire.`,fix:`Sortir prioritairement du côté de son épaule avant (extérieur).`},{error:`Les pieds se croisent pendant le pas.`,fix:`Le pied le plus proche de la direction part en premier, l’autre suit.`}],criteria:[`Les pieds ne se croisent jamais.`,`Après le déplacement, le boxeur est hors de la ligne au sol, en garde face au partenaire.`,`Le choix pivot/pas latéral tient compte des plots-cordes.`],adaptations:{enfants:`Jeu du « taureau qui passe » : le partenaire avance doucement, l’enfant s’écarte comme un toréador, sans défense préalable.`,ados:`Ajouter la parade avant le pas et chronométrer le temps de réaction.`,jeunesAdultes:`Finir chaque sortie par un enchaînement de deux coups dans le vide depuis l’angle obtenu.`},safety:`Le partenaire avance lentement et s’arrête à un mètre minimum ; zone dégagée de tout obstacle, plots bas uniquement.`},{id:29,slug:`defense-remise-dans-le-vide`,module:3,title:`Défense puis remise immédiate`,level:`avancé`,durationMin:20,objective:`Transformer chaque défense en point de départ d’une remise adaptée (direct, crochet ou uppercut dans le vide), sans temps mort ni déséquilibre.`,prerequisites:[`Rouler sous le crochet`,`Parade chassée du direct`,`Enchaînements du direct`],organisation:{space:`Ring ou salle, binômes à trois mètres derrière des plots.`,material:[`Plots`,`Cartes illustrées défense / remise`,`Chronomètre`],groups:`Binômes ; l’entraîneur tire les cartes pour l’ensemble du groupe.`},schema:{kind:`enchainement`,phases:[`Défense choisie`,`Remise adaptée`,`Retour en garde mobile`]},steps:[`Revoir les associations clés : parade → direct arrière, retrait → direct arrière, esquive → crochet, flexion → uppercut (1 répétition lente de chaque, 3 tours).`,`L’entraîneur tire une carte défense, chacun exécute défense + remise dans le vide (2 x 6).`,`Le partenaire mime lentement une attaque annoncée derrière son plot ; le boxeur défend et remise vers le vide, à côté du partenaire (2 x 8).`,`Ajouter un pas de sortie après la remise (2 x 6).`,`Round de 2 min : attaques mimées non annoncées, rythme lent ; le partenaire valide ou corrige chaque association.`],decision:`Après une esquive à l’extérieur, le boxeur choisit entre remiser du bras libéré ou ressortir sans remise si le partenaire mime déjà une seconde attaque.`,corrections:[{error:`Pause entre défense et remise.`,fix:`Penser défense et remise comme un seul mot : « es-quive-cro-chet ».`},{error:`Remise lancée vers le partenaire.`,fix:`Viser un point fixe à côté de lui (plot haut ou repère au mur).`},{error:`Garde oubliée après la remise.`,fix:`Compter « trois » : défense, remise, garde.`}],criteria:[`La remise part en moins d’une seconde après la défense.`,`Le type de remise correspond à la défense dans 8 cas sur 10.`,`Le boxeur termine chaque séquence en garde équilibrée.`],adaptations:{enfants:`Uniquement avec les cartes et sans partenaire mimant ; deux associations au choix maximum.`,ados:`Partenaire qui mime, attaques annoncées, défi de fluidité noté par l’observateur.`,jeunesAdultes:`Attaques non annoncées au rythme lent et ajout de la sortie en angle.`},safety:`Toute remise se fait dans le vide, jamais en direction du visage ou du corps du partenaire ; distance de trois mètres maintenue par les plots.`},{id:30,slug:`lecture-des-signaux-defensifs`,module:3,title:`Lecture des signaux et choix défensif`,level:`avancé`,durationMin:25,objective:`Identifier rapidement le type d’attaque mimée à partir d’indices (épaule, pied, hauteur du bras) et choisir la défense la plus adaptée parmi celles du module.`,prerequisites:[`Défense puis remise immédiate`,`Sortir de l’axe par pas latéral`],organisation:{space:`Ring entier ou zone de 5 x 5 m, plots délimitant une distance de sécurité de trois mètres.`,material:[`Plots`,`Balles en mousse de couleur`,`Fiche d’observation`,`Chronomètre`],groups:`Groupes de trois : attaquant qui mime, défenseur, observateur qui note.`},schema:{kind:`cooperation`,phases:[`Indice observé`,`Défense choisie`,`Observateur valide`]},steps:[`Présentation des indices : épaule avant qui part = direct, coude qui s’ouvre = crochet, genoux qui fléchissent = uppercut (démonstration lente, 5 min).`,`L’attaquant montre l’indice seul, sans le coup : le défenseur nomme l’attaque à voix haute (2 x 8).`,`L’attaquant mime le coup complet très lentement : le défenseur choisit et exécute une défense (2 x 8).`,`Ajouter une remise et une sortie, l’observateur coche la fiche (2 x 6).`,`Round de 2 min à rythme lent avec attaques variées, puis échange de rôles et bilan collectif sur les erreurs de lecture.`],decision:`Face à un même indice, plusieurs défenses sont possibles : le défenseur justifie son choix après le round (« j’ai roulé car j’étais près des plots »).`,corrections:[{error:`Le défenseur réagit à la voix et non à l’indice visuel.`,fix:`L’attaquant reste silencieux ; seuls les gestes renseignent.`},{error:`Toujours la même défense quelle que soit l’attaque.`,fix:`L’observateur interdit pendant 30 s la défense trop utilisée.`}],criteria:[`L’attaque est correctement nommée dans au moins 8 cas sur 10.`,`Au moins trois défenses différentes sont utilisées pendant le round.`,`Le défenseur sait expliquer un choix à l’observateur.`],adaptations:{enfants:`Balles de couleur à la place des mimes (rouge = esquive, jaune = couverture, vert = pas arrière) ; parties courtes de 45 s.`,ados:`Mimes réels mais très lents, fiche d’observation simplifiée à deux colonnes.`,jeunesAdultes:`Indices plus discrets, feintes d’indice ajoutées, discussion tactique à la fin de chaque round.`},safety:`Les mimes se font derrière les plots, trois mètres minimum, à vitesse lente imposée ; l’observateur peut arrêter l’exercice à tout moment.`}];var g=[{id:31,slug:`reperer-sa-distance`,module:4,title:`Repérer sa distance de touche`,level:`découverte`,durationMin:15,objective:`Connaître sa propre allonge et distinguer trois distances : hors de portée, distance de touche, trop près.`,prerequisites:[`Garde de base et position des appuis`,`Direct du bras avant dans le vide`],organisation:{space:`Mur ou espalier dégagé, puis couloirs de quatre mètres balisés au sol.`,material:[`Plots de trois couleurs`,`Ruban adhésif`,`Mètre ruban`],groups:`Individuel, puis binômes d’allonge proche.`},schema:{kind:`distance`,phases:[`Zone longue (hors portée)`,`Zone de touche`,`Zone courte`]},steps:[`Face à un plot haut, lancer un direct dans le vide et ajuster sa position jusqu’à ce que le gant s’arrête juste avant le plot (5 essais).`,`Marquer au sol trois zones avec les plots : rouge = trop près, vert = touche, bleu = hors portée (installation guidée).`,`Se déplacer en pas chassés et annoncer à voix haute la zone où l’on se trouve (1 min).`,`Sur un appel de couleur de l’entraîneur, rejoindre la zone en deux pas maximum (2 x 8).`,`En binôme, l’un se place, l’autre estime à l’œil sa propre zone par rapport au partenaire puis vérifie au plot (2 x 6).`],decision:`À l’appel « attaque », le boxeur décide s’il est déjà en zone verte ou s’il doit d’abord avancer d’un pas avant de lancer son direct dans le vide.`,corrections:[{error:`Le boxeur se penche pour « gagner » de l’allonge.`,fix:`Le buste reste au-dessus des appuis : c’est le pas qui règle la distance.`},{error:`Confusion entre zones à cause de pas trop grands.`,fix:`Petits pas de la longueur d’un pied pour ajuster finement.`}],criteria:[`Le boxeur s’arrête dans la bonne zone en deux pas maximum.`,`Son direct dans le vide s’arrête à moins de dix centimètres du plot.`,`Il estime correctement sa zone face au partenaire dans 4 cas sur 6.`],adaptations:{enfants:`Jeu des « trois maisons » de couleur ; zones larges et appels lents.`,ados:`Zones resserrées et appels enchaînés rapidement ; défi de précision.`,jeunesAdultes:`Mesurer son allonge réelle et la comparer à celle de partenaires de gabarits différents.`},safety:`Les directs se font vers un plot, jamais vers un partenaire ; dégager l’espace autour du mur ou de l’espalier.`},{id:32,slug:`entrer-et-sortir-de-distance`,module:4,title:`Entrer et sortir de distance`,level:`découverte`,durationMin:15,objective:`Passer de la zone longue à la zone de touche et ressortir aussitôt, en un aller-retour rapide et équilibré.`,prerequisites:[`Repérer sa distance de touche`,`Pas chassés avant/arrière`],organisation:{space:`Couloirs de quatre mètres avec les trois zones de couleur au sol.`,material:[`Plots de couleur`,`Plot haut comme cible fixe`,`Chronomètre`],groups:`Individuel en couloir, puis vagues de quatre boxeurs.`},schema:{kind:`deplacement`,phases:[`Attente zone longue`,`Entrée + direct`,`Sortie immédiate`]},steps:[`Aller-retour lent zone bleue → zone verte → zone bleue en pas chassés, garde haute (2 x 8).`,`Ajouter un direct dans le vide vers le plot haut à l’arrivée en zone verte (2 x 8).`,`Accélérer l’entrée en gardant une sortie aussi rapide que l’entrée (2 x 6).`,`Sur un claquement de mains, entrer ; sur deux claquements, rester et feinter (1 min).`,`Vagues : quatre boxeurs exécutent dix allers-retours, l’entraîneur observe la stabilité à la sortie.`],decision:`Après l’entrée, si l’entraîneur lève la main, le boxeur doit ressortir sans lancer son direct : il décide en zone verte s’il frappe dans le vide ou s’il repart.`,corrections:[{error:`Le boxeur reste planté en zone verte après le direct.`,fix:`Penser « entrer-toucher-sortir » comme un seul mouvement.`},{error:`Sortie en reculant le buste uniquement.`,fix:`Le pied arrière pousse vers l’arrière, le corps suit en entier.`}],criteria:[`Le temps passé en zone verte ne dépasse pas une seconde.`,`La garde reste haute à l’entrée et à la sortie.`,`Le boxeur respecte le signal « pas de direct » dans 8 cas sur 10.`],adaptations:{enfants:`Image du « chat qui vole un poisson et repart » ; pas de feinte, seulement entrée-sortie.`,ados:`Défi chronométré : nombre d’allers-retours propres en 30 s.`,jeunesAdultes:`Varier les angles d’entrée (axe et légèrement latéral) et ajouter le double direct dans le vide.`},safety:`Un seul boxeur par couloir ; les plots-cibles sont légers et le sol dégagé pour éviter les chutes en recul.`},{id:33,slug:`garder-la-distance-en-miroir`,module:4,title:`Garder la distance en miroir`,level:`découverte`,durationMin:15,objective:`Maintenir une distance constante avec un partenaire mobile en suivant ses déplacements, sans aucun geste de frappe.`,prerequisites:[`Entrer et sortir de distance`,`Pas chassés latéraux`],organisation:{space:`Salle libre, binômes répartis avec deux mètres de marge autour.`,material:[`Bâton léger en mousse ou corde de 2 m`,`Chronomètre`],groups:`Binômes : un meneur, un suiveur ; inversion toutes les 45 s.`},schema:{kind:`cooperation`,phases:[`Meneur se déplace`,`Suiveur ajuste`,`Distance conservée`]},steps:[`Les deux partenaires tiennent chacun un bout de la corde tendue sans tirer : le meneur avance/recule lentement, le suiveur garde la corde tendue (1 min).`,`Même exercice avec déplacements latéraux et pivots (1 min).`,`Lâcher la corde : garder la même distance « à l’œil », le meneur change d’allure (2 x 45 s).`,`Le meneur s’arrête brusquement : le suiveur doit s’arrêter sans franchir la distance (2 x 8).`,`Le suiveur prend l’initiative de changer de zone (entrée feinte) au signal de l’entraîneur, puis revient à la distance de départ (1 min).`],decision:`Quand le meneur recule vers un plot figurant les cordes, le suiveur choisit de le suivre de face ou de se décaler pour lui couper la sortie latérale.`,corrections:[{error:`Le suiveur réagit en retard et la distance se rallonge.`,fix:`Regarder les hanches du meneur, elles annoncent le déplacement.`},{error:`Pieds qui se croisent sur les déplacements latéraux.`,fix:`Pas chassés courts, pied le plus proche de la direction en premier.`}],criteria:[`La corde reste tendue sans tirer pendant tout l’exercice.`,`Sans corde, la distance varie de moins d’un demi-pas.`,`Le suiveur s’arrête à temps sur les arrêts brusques.`],adaptations:{enfants:`Jeu de « l’ombre » avec la corde uniquement ; meneur lent et trajets simples.`,ados:`Sans corde, rôle de meneur avec changements d’allure imprévisibles.`,jeunesAdultes:`Le suiveur doit en plus couper l’angle vers les plots-cordes à chaque recul.`},safety:`La corde n’est jamais enroulée autour du poignet et se lâche au moindre déséquilibre ; aucun geste de bras vers le partenaire.`},{id:34,slug:`changer-de-tempo`,module:4,title:`Changer de tempo`,level:`intermédiaire`,durationMin:18,objective:`Varier volontairement la vitesse de ses déplacements et de ses coups dans le vide pour casser la régularité et surprendre.`,prerequisites:[`Entrer et sortir de distance`,`Enchaînements du direct`],organisation:{space:`Salle libre, chacun dans un espace de 2 x 2 m.`,material:[`Musique ou métronome à tempo variable`,`Plots`],groups:`Individuel, puis binômes observateur/boxeur.`},schema:{kind:`enchainement`,phases:[`Tempo lent installé`,`Rupture rapide`,`Retour au calme`]},steps:[`Shadow sur un tempo lent et régulier (métronome) : pas + direct dans le vide sur chaque temps (1 min).`,`Sur le même tempo, insérer un enchaînement de deux coups rapides tous les quatre temps (2 x 1 min).`,`Alterner « lent-lent-vite » sans métronome, l’observateur doit repérer le moment de rupture (2 x 45 s).`,`Ralentir volontairement juste avant d’accélérer (temps mort trompeur) (2 x 6).`,`Round de 1 min 30 : l’observateur frappe dans ses mains à chaque rupture vue ; s’il les annonce toutes, le boxeur est trop prévisible.`],decision:`Le boxeur choisit le moment de sa rupture : juste après un déplacement de l’observateur ou au moment où celui-ci baisse les yeux.`,corrections:[{error:`Accélération uniquement des bras, pieds restés lents.`,fix:`Les pieds lancent la rupture, les bras suivent.`},{error:`Ruptures toujours au même intervalle.`,fix:`Compter dans sa tête des cycles différents (3, 5, 2...).`},{error:`Perte de garde pendant l’accélération.`,fix:`Raccourcir les coups plutôt que les allonger.`}],criteria:[`Le passage du lent au rapide est net et visible.`,`L’observateur n’anticipe pas plus de la moitié des ruptures.`,`La garde reste haute pendant les phases rapides.`],adaptations:{enfants:`Jeu « tortue / lièvre » à l’appel de l’entraîneur, uniquement sur les déplacements.`,ados:`Ruptures choisies librement, défi contre l’observateur.`,jeunesAdultes:`Travail des trois vitesses (lent, moyen, explosif) et du temps mort trompeur.`},safety:`Chaque boxeur reste dans son carré pour éviter les collisions lors des accélérations ; coups toujours dans le vide.`},{id:35,slug:`feinte-et-observation`,module:4,title:`Feinte et observation de la réaction`,level:`intermédiaire`,durationMin:18,objective:`Utiliser une feinte d’épaule ou de pied pour provoquer une réaction du partenaire, et apprendre à lire cette réaction.`,prerequisites:[`Changer de tempo`,`Garder la distance en miroir`],organisation:{space:`Binômes à trois mètres, distance balisée par deux plots.`,material:[`Plots`,`Foulards`,`Fiche d’observation simple`],groups:`Binômes ; inversion des rôles toutes les 2 min.`},schema:{kind:`cooperation`,phases:[`Feinte proposée`,`Réaction du partenaire`,`Décision du feinteur`]},steps:[`Au miroir, feinte d’épaule avant (petit départ de direct sans bras) et feinte de pied (petit appel au sol) (2 x 8).`,`Le partenaire réagit de façon imposée : il lève les gants sur la feinte d’épaule (2 x 6).`,`Le partenaire choisit sa réaction : lever les gants, reculer ou ne rien faire ; le feinteur nomme à voix haute la réaction vue (2 x 8).`,`Feinte puis action dans le vide adaptée : si le partenaire lève les gants, direct au corps dans le vide ; s’il recule, entrée d’un pas (2 x 6).`,`Round de 1 min 30 sans annonce ; à la fin, le feinteur dit quelle feinte « marche » le mieux sur ce partenaire.`],decision:`Après la feinte, le boxeur décide entre attaquer dans le vide (réaction exploitée), refeinter (réaction absente) ou ressortir (partenaire qui avance).`,corrections:[{error:`Feinte trop ample qui déséquilibre le feinteur.`,fix:`La feinte est un « début » de geste, pas un geste raté.`},{error:`Le feinteur ne regarde pas la réaction.`,fix:`Les yeux restent fixés sur les gants et le buste du partenaire.`}],criteria:[`Le feinteur nomme correctement la réaction dans 8 cas sur 10.`,`Il reste équilibré et en garde après chaque feinte.`,`L’action qui suit correspond à la réaction observée.`],adaptations:{enfants:`Jeu « Jacques a dit » à l’envers : on fait semblant et le partenaire ne doit pas bouger ; uniquement feinte de pied.`,ados:`Réactions libres et fiche d’observation à cocher par un troisième élève.`,jeunesAdultes:`Enchaîner deux feintes différentes pour observer laquelle déclenche la réaction attendue.`},safety:`Toute action après la feinte se fait dans le vide, à côté du partenaire ; plots à trois mètres jamais franchis.`},{id:36,slug:`couper-la-sortie`,module:4,title:`Couper la sortie`,level:`intermédiaire`,durationMin:20,objective:`Diriger un partenaire qui se déplace vers un coin ou des cordes en coupant ses angles de sortie par des pas latéraux, sans le poursuivre en ligne droite.`,prerequisites:[`Garder la distance en miroir`,`Pivot sur le pied avant`],organisation:{space:`Ring ou carré de 4 x 4 m délimité par des plots ; coins bien visibles.`,material:[`Plots`,`Chasubles de deux couleurs`,`Chronomètre`],groups:`Binômes : un « pilote » qui coupe, un « mobile » qui se déplace ; inversion toutes les minutes.`},schema:{kind:`deplacement`,phases:[`Mobile au centre`,`Pilote coupe l’angle`,`Mobile orienté vers le coin`]},steps:[`Démonstration à vitesse marchée : le pilote se place en diagonale et non face au mobile (2 passages commentés).`,`Le mobile se déplace uniquement latéralement ; le pilote fait un pas latéral du même côté pour lui « fermer la porte » (2 x 45 s).`,`Le mobile peut avancer, reculer ou tourner ; le pilote doit l’amener vers un coin en moins de 30 s (3 essais).`,`Ajouter un direct dans le vide du pilote quand le mobile arrive près du coin, à distance de sécurité (2 x 30 s).`,`Jeu : on compte combien de fois le pilote amène le mobile dans un coin en 1 min, à allure de marche rapide.`],decision:`Quand le mobile hésite entre deux sorties, le pilote choisit de fermer la plus large et de laisser volontairement la plus étroite, qui mène au coin.`,corrections:[{error:`Le pilote suit le mobile en ligne droite.`,fix:`Faire un pas latéral avant tout pas avant : « couper avant de presser ».`},{error:`Le pilote arrive trop près et doit reculer.`,fix:`S’arrêter en limite de zone longue, jamais en zone courte.`},{error:`Pieds qui se croisent au moment de couper.`,fix:`Pas chassés courts, garde orientée vers le mobile.`}],criteria:[`Le pilote se trouve en diagonale du mobile la majorité du temps.`,`Le mobile est amené dans un coin en moins de 30 s.`,`La distance de sécurité de deux mètres est toujours respectée.`],adaptations:{enfants:`Jeu du « berger et du mouton » en marchant, sans coup ; coins larges.`,ados:`Allure de marche rapide et comptage des réussites.`,jeunesAdultes:`Le mobile a le droit de feinter ; le pilote doit garder sa diagonale malgré les feintes.`},safety:`Allure de marche rapide maximum, aucun contact corporel ; distance minimale de deux mètres, l’exercice s’arrête si elle n’est pas respectée.`},{id:37,slug:`contrer-le-pas-avant`,module:4,title:`Saisir le temps sur le pas avant`,level:`avancé`,durationMin:20,objective:`Repérer l’instant où le partenaire avance (pied en l’air) et choisir de lancer son action dans le vide à ce moment précis.`,prerequisites:[`Feinte et observation de la réaction`,`Repérer sa distance de touche`],organisation:{space:`Couloirs de cinq mètres avec zones de couleur au sol, binômes face à face.`,material:[`Plots de couleur`,`Plot haut comme cible latérale`,`Chronomètre`],groups:`Binômes ; l’entraîneur donne le rythme des avancées.`},schema:{kind:`distance`,phases:[`Partenaire avance`,`Pied en l’air = signal`,`Direct dans le vide`]},steps:[`Le partenaire avance d’un pas lent et exagéré ; le boxeur dit « top » quand le pied avant quitte le sol (2 x 8).`,`Même travail, mais le boxeur lance un direct dans le vide vers le plot latéral sur le « top » (2 x 8).`,`Le partenaire varie entre pas lent, pas rapide et faux départ (pied qui ne part pas) (2 x 8).`,`Le boxeur ajoute un pas de sortie après son action (2 x 6).`,`Round de 1 min 30 : le partenaire avance librement au rythme lent imposé, le boxeur choisit ses moments ; bilan des « tops » réussis.`],decision:`Sur un faux départ, le boxeur doit choisir de ne pas partir ; sur un pas trop long qui le met en zone courte, il préfère sortir latéralement que lancer son action.`,corrections:[{error:`Départ sur le mouvement des épaules au lieu du pied.`,fix:`Regarder le bas du corps du partenaire, genoux et pieds.`},{error:`Action lancée trop tard, après la pose du pied.`,fix:`Être déjà en appui prêt, poids légèrement sur l’avant.`}],criteria:[`Le « top » est donné pendant que le pied est en l’air dans 8 cas sur 10.`,`Aucune réaction sur les faux départs.`,`La sortie suit l’action sans temps d’arrêt.`],adaptations:{enfants:`Jeu « feu rouge / feu vert » : on ne bouge que quand le pied du partenaire décolle ; uniquement le « top » vocal.`,ados:`Ajouter le direct dans le vide et les faux départs, défi à points.`,jeunesAdultes:`Travailler aussi le temps sur le recul du partenaire et comparer les deux situations.`},safety:`Le partenaire avance lentement et s’arrête toujours avant la zone courte ; les directs visent un plot latéral, jamais le partenaire.`},{id:38,slug:`jeu-de-distance-a-trois-zones`,module:4,title:`Jeu de distance à trois zones`,level:`avancé`,durationMin:20,objective:`Choisir en continu la zone (longue, de touche, courte) la plus favorable selon la position du partenaire et l’espace restant.`,prerequisites:[`Couper la sortie`,`Entrer et sortir de distance`],organisation:{space:`Ring ou carré de 5 x 5 m, plots-cordes sur les bords.`,material:[`Plots`,`Cartes de consigne`,`Chronomètre`,`Fiche d’observation`],groups:`Groupes de trois : deux boxeurs en shadow face à face, un observateur.`},schema:{kind:`distance`,phases:[`Lecture de l’espace`,`Choix de zone`,`Action ou sortie`]},steps:[`Rappel des trois zones et de leur intérêt : longue pour observer, de touche pour agir, courte à éviter sans projet (5 min).`,`Shadow face à face sans coup : chacun annonce la zone où il veut être et s’y place (2 x 1 min).`,`Cartes de consigne tirées par l’observateur (« reste en longue », « entre et sors ») : le boxeur doit l’appliquer malgré les déplacements de l’autre (2 x 1 min).`,`Ajouter les coups dans le vide uniquement en zone de touche et sur le côté du partenaire (2 x 1 min).`,`Round libre de 2 min à rythme lent ; l’observateur note les moments passés en zone courte sans projet.`],decision:`Près des plots-cordes, le boxeur choisit entre ressortir vers le centre (zone longue) ou entrer volontairement en zone de touche pour agir avant d’être coincé.`,corrections:[{error:`Le boxeur subit la distance imposée par l’autre.`,fix:`Annoncer intérieurement sa zone cible avant chaque déplacement.`},{error:`Séjours prolongés en zone courte.`,fix:`Règle : en zone courte, on sort en moins de deux secondes.`}],criteria:[`La consigne de zone est respectée au moins 70 % du round.`,`Aucun séjour de plus de deux secondes en zone courte.`,`Les coups dans le vide ne partent qu’en zone de touche.`],adaptations:{enfants:`Jeu de déplacement avec trois cerceaux de couleur posés au sol, sans partenaire face à soi.`,ados:`Shadow face à face avec cartes de consigne, rounds de 1 min.`,jeunesAdultes:`Cartes contradictoires entre les deux boxeurs (l’un veut la longue, l’autre la touche) pour créer un vrai rapport de force tactique.`},safety:`Les coups sont lancés dans le vide, à côté du partenaire ; la zone courte reste à plus d’un mètre et l’observateur arrête en cas de rapprochement.`},{id:39,slug:`gerer-l-effort-sur-le-round`,module:4,title:`Gérer son effort sur le round`,level:`avancé`,durationMin:22,objective:`Répartir son énergie sur un round en alternant phases de récupération active et temps forts, et savoir quand placer ces derniers.`,prerequisites:[`Changer de tempo`,`Jeu de distance à trois zones`],organisation:{space:`Salle libre, un carré de 3 x 3 m par boxeur.`,material:[`Chronomètre avec signal sonore`,`Fiche de ressenti (échelle de 1 à 10)`,`Gourdes`],groups:`Individuel, puis binômes boxeur/coach.`},schema:{kind:`enchainement`,phases:[`Récupération active`,`Temps fort de 10 s`,`Retour au calme`]},steps:[`Shadow en récupération active (déplacements souples, respiration nasale) pendant 1 min ; noter son ressenti de 1 à 10.`,`Round de 2 min : deux temps forts de 10 s placés au signal de l’entraîneur (fin de round incluse).`,`Round de 2 min : le boxeur choisit lui-même où placer ses deux temps forts ; le binôme note les moments.`,`Discussion de 2 min : où placer un temps fort (début pour marquer, fin pour conclure, après une sortie réussie) ?`,`Round final de 2 min avec trois temps forts choisis ; comparer le ressenti avec le premier round.`],decision:`À 30 s de la fin, fatigué, le boxeur décide entre un dernier temps fort ou une récupération pour finir lucide ; il justifie son choix au binôme.`,corrections:[{error:`Tout le round à fond puis effondrement.`,fix:`Garder un rythme où l’on peut encore parler en phase de récupération.`},{error:`Récupération immobile, pieds plantés.`,fix:`Continuer à bouger et à garder la garde : la récupération est active.`},{error:`Respiration bloquée pendant les temps forts.`,fix:`Souffler à chaque coup dans le vide.`}],criteria:[`Les temps forts sont nettement distincts des phases de récupération.`,`Le boxeur termine le round en garde et en mouvement.`,`Il sait expliquer pourquoi il a placé ses temps forts à ces moments.`],adaptations:{enfants:`Rounds de 1 min, un seul temps fort de 5 s annoncé par l’entraîneur ; jeu de « la fusée qui décolle ».`,ados:`Rounds de 1 min 30, deux temps forts choisis et fiche de ressenti simplifiée.`,jeunesAdultes:`Rounds de 2 à 3 min, trois temps forts et suivi de la récupération entre rounds.`},safety:`Hydratation entre chaque round ; tout boxeur qui note 9 ou 10 de ressenti passe en récupération marchée. Shadow uniquement, aucun partenaire à portée.`},{id:40,slug:`scenarios-tactiques-sans-contact`,module:4,title:`Scénarios tactiques sans contact`,level:`avancé`,durationMin:25,objective:`Mettre en œuvre distance, tempo, feintes et défense dans des scénarios imposés (adversaire plus grand, qui avance, qui fuit), en prenant des décisions argumentées.`,prerequisites:[`Jeu de distance à trois zones`,`Saisir le temps sur le pas avant`,`Lecture des signaux et choix défensif`],organisation:{space:`Ring ou carré de 5 x 5 m délimité par des plots-cordes, zone d’observation à l’extérieur.`,material:[`Cartes scénario`,`Plots`,`Chronomètre`,`Fiche de débriefing`],groups:`Groupes de trois : deux boxeurs en shadow face à face, un observateur ; rotation à chaque scénario.`},schema:{kind:`cooperation`,phases:[`Scénario tiré`,`Plan annoncé puis appliqué`,`Débriefing à trois`]},steps:[`Présenter trois scénarios : « il avance sans arrêt », « il garde la distance longue », « il fuit vers les côtés » (3 min).`,`Le boxeur tire une carte et annonce son plan en une phrase à l’observateur (ex. « je coupe à gauche et je saisis le temps ») (1 min).`,`Le partenaire joue le scénario à rythme lent, sans coup ; le boxeur applique son plan avec actions dans le vide (round de 1 min 30).`,`Débriefing de 1 min : l’observateur dit si le plan a été suivi et ce qui a fonctionné.`,`Rejouer le même scénario en corrigeant un point, puis rotation des rôles (round de 1 min 30).`],decision:`Si le plan annoncé ne fonctionne pas après 30 s (ex. l’adversaire ne se laisse pas couper), le boxeur décide d’en changer et doit pouvoir dire lequel il a choisi et pourquoi.`,corrections:[{error:`Le boxeur oublie son plan dès le début du round.`,fix:`Le résumer en deux mots clés répétés intérieurement (« couper, temps »).`},{error:`Le partenaire accélère et l’exercice devient un combat.`,fix:`L’observateur rappelle le rythme lent imposé et arrête si besoin.`}],criteria:[`Le plan est annoncé clairement avant le round.`,`L’observateur reconnaît au moins deux actions conformes au plan.`,`Le boxeur identifie lui-même un point à améliorer lors du débriefing.`],adaptations:{enfants:`Scénarios sous forme d’histoires (« le géant », « le lapin qui fuit ») en déplacements seuls, débriefing guidé par l’entraîneur.`,ados:`Deux scénarios seulement, plans proposés sous forme de choix multiples.`,jeunesAdultes:`Scénarios combinés et changement de plan obligatoire à mi-round sur signal.`},safety:`Aucun coup en direction du partenaire : toutes les actions se font dans le vide, à plus d’un mètre ; rythme lent imposé et l’observateur peut stopper le scénario à tout moment.`}];var h=[{id:41,slug:`echauffement-autonome`,module:5,title:`Construire son échauffement autonome`,level:`découverte`,durationMin:15,objective:`Savoir conduire seul un échauffement complet de boxe éducative (articulaire, cardio, appuis, gestes à vide) en suivant une logique progressive.`,prerequisites:[`Module 1 : garde et appuis de base`,`Module 1 : sautillés et coordination`,`Module 2 : coups droits dans le vide`],organisation:{space:`Salle ou cour, un carré de 2 m × 2 m par boxeur, délimité par quatre plots.`,material:[`4 plots par boxeur`,`Cartes « étapes » plastifiées (articulaire, cardio, appuis, gestes)`,`Chronomètre ou minuteur de salle`],groups:`Travail individuel, l’éducateur circule ; possibilité de binôme « lecteur de cartes » pour les plus jeunes.`},schema:{kind:`appuis`,phases:[`Réveil articulaire de la tête aux chevilles`,`Montée cardio en sautillés dans le carré`,`Appuis et gestes à vide de plus en plus rapides`]},steps:[`Présenter les quatre cartes dans l’ordre et expliquer pourquoi on va du plus doux au plus intense (préparer articulations, cœur, puis gestes).`,`Chaque boxeur pose ses cartes au sol devant son carré et réalise 2 min de mobilisation articulaire (cou, épaules, poignets, hanches, genoux, chevilles) sans aide.`,`Enchaîner 3 min de montée cardio dans le carré : sautillés, pas chassés d’un plot à l’autre, montées de genoux légères, en gardant la garde haute.`,`Passer à 3 min d’appuis et gestes à vide : pas avant-arrière, pivots, puis direct-direct et crochets dans le vide à vitesse progressive.`,`Terminer par 1 min de retour au calme respiratoire, puis chaque boxeur annonce à voix haute l’ordre suivi et le moment où il s’est senti « prêt ».`],decision:`À la carte « cardio », le boxeur choisit lui-même l’intensité (1, 2 ou 3) selon son ressenti et doit la justifier (froid, fatigue, forme du jour).`,corrections:[{error:`Commencer directement par des coups rapides sans préparation articulaire.`,fix:`Remettre la carte « articulaire » en premier et faire compter 5 cercles lents par articulation avant tout geste.`},{error:`Garde qui tombe pendant les sautillés.`,fix:`Consigne « poings aux pommettes » répétée à chaque changement de carte, vérification au miroir si disponible.`},{error:`Intensité maximale dès la deuxième minute.`,fix:`Utiliser l’échelle 1-2-3 : rester sur 1 la première minute, 2 ensuite, 3 seulement sur les 30 dernières secondes.`}],criteria:[`Les quatre étapes sont réalisées dans l’ordre sans rappel de l’éducateur.`,`L’intensité augmente visiblement de l’étape 1 à l’étape 4.`,`La garde reste haute et les appuis restent dans le carré pendant les gestes à vide.`],adaptations:{enfants:`Cartes illustrées avec dessins d’animaux (« le chat qui s’étire », « le lapin qui sautille »), durée réduite à 8 min et un binôme lit les cartes à voix haute.`,ados:`Chaque ado ajoute un exercice de son choix dans une étape et doit l’expliquer au groupe ; durée complète de 10 min.`,jeunesAdultes:`Construction d’une fiche d’échauffement personnelle écrite, adaptée à leurs points faibles, à réutiliser avant chaque séance.`},safety:`Aucun contact : chaque boxeur reste dans son carré, au moins 1,5 m entre deux carrés ; arrêt immédiat en cas de douleur articulaire signalée.`},{id:42,slug:`auto-evaluation-au-miroir`,module:5,title:`S’auto-évaluer au miroir`,level:`découverte`,durationMin:15,objective:`Apprendre à observer sa propre garde, ses appuis et un enchaînement simple pour repérer seul un point fort et un point à améliorer.`,prerequisites:[`Module 1 : garde et appuis de base`,`Module 2 : enchaînement direct-direct-crochet dans le vide`],organisation:{space:`Face au mur de miroirs, une place de 1,5 m de large par boxeur, ligne au sol à 2 m du miroir.`,material:[`Miroir mural (ou tablette pour filmer si pas de miroir)`,`Grille d’auto-évaluation papier à 3 cases`,`Crayons`,`Chronomètre`],groups:`Individuel, par vagues de 4 à 6 boxeurs face au miroir, les autres remplissent leur grille.`},schema:{kind:`enchainement`,phases:[`Se placer en garde face au miroir`,`Réaliser l’enchaînement lentement puis à vitesse normale`,`Remplir sa grille : un point fort, un point à travailler`]},steps:[`Montrer la grille : « garde » (poings, coudes, menton), « appuis » (largeur, talon arrière), « retour en garde » ; chaque case se note vert, orange ou rouge.`,`Le boxeur se place sur la ligne, prend sa garde et la tient 10 secondes en s’observant sans bouger : il remplit la case « garde ».`,`Il réalise trois fois l’enchaînement direct-direct-crochet au ralenti en regardant ses pieds puis ses mains : il remplit la case « appuis ».`,`Il réalise l’enchaînement 5 fois à vitesse normale en se concentrant sur le retour en garde : il remplit la dernière case.`,`Il choisit un seul point « orange » ou « rouge », refait 5 répétitions en se corrigeant, puis indique à l’éducateur ce qui a changé.`],decision:`Le boxeur décide lui-même quel point travailler en priorité et explique pourquoi ce point est le plus important pour sa sécurité ou son efficacité.`,corrections:[{error:`Tout noter en vert sans s’observer vraiment.`,fix:`L’éducateur demande de décrire précisément ce qu’il voit (« où est ton coude arrière ? ») avant de valider la couleur.`},{error:`Regarder le miroir en baissant le menton ou en tournant la tête.`,fix:`Fixer un repère sur le miroir à hauteur des yeux et ne regarder ses pieds qu’au ralenti.`}],criteria:[`La grille est remplie avec au moins une case non verte justifiée par une observation concrète.`,`Le boxeur nomme un point fort et un point à travailler avec le vocabulaire de la boxe.`,`Une amélioration visible du point choisi apparaît sur les 5 dernières répétitions.`],adaptations:{enfants:`Grille avec smileys au lieu des couleurs et seulement deux cases (garde, retour en garde) ; l’éducateur pose les questions à voix haute.`,ados:`Grille complète et comparaison avec la grille de la séance précédente pour mesurer leur progression.`,jeunesAdultes:`Ajout d’une vidéo courte filmée par eux-mêmes et d’une quatrième case « rythme », avec objectif écrit pour la semaine.`},safety:`Rester derrière la ligne au sol pour ne jamais frapper le miroir ; espacement latéral de 1,5 m pour éviter de toucher un voisin.`},{id:43,slug:`assembler-appuis-et-enchainements`,module:5,title:`Assembler appuis, enchaînements et défense à vide`,level:`découverte`,durationMin:20,objective:`Relier dans une même séquence à vide un déplacement, un enchaînement de deux ou trois coups et une action défensive, avec retour en garde.`,prerequisites:[`Module 1 : déplacements avant-arrière et latéraux`,`Module 2 : enchaînements de deux et trois coups`,`Module 3 : esquive rotative et retrait`],organisation:{space:`Couloir de 6 m par boxeur, balisé par trois plots de couleur (départ, zone d’action, zone de sortie).`,material:[`3 plots de couleurs différentes par couloir`,`Cartes « défense » (esquive, retrait, parade)`,`Chronomètre`],groups:`Individuel par couloir, 3 à 4 boxeurs par couloir qui passent à tour de rôle.`},schema:{kind:`enchainement`,phases:[`Entrée en pas avant jusqu’au plot d’action`,`Enchaînement à vide puis défense tirée sur carte`,`Sortie en pas latéral et garde tenue 2 secondes`]},steps:[`Démontrer la séquence complète lentement : deux pas avant, direct-direct, esquive rotative, sortie latérale, garde tenue.`,`Premier passage au ralenti : chaque boxeur annonce à voix haute chaque phase (« j’avance, je frappe, je défends, je sors »).`,`Deuxième passage à vitesse moyenne : l’éducateur montre une carte « défense » au moment où le boxeur termine son enchaînement.`,`Troisième passage : le boxeur choisit l’enchaînement (2 ou 3 coups) et réagit à la carte défense montrée au hasard.`,`Série finale de 3 passages chronométrés à 6 secondes maximum, en gardant la qualité du retour en garde.`],decision:`Selon la carte montrée (esquive, retrait, parade), le boxeur adapte sa défense puis choisit la sortie la plus logique (côté gauche ou droit).`,corrections:[{error:`Pieds qui s’arrêtent net entre l’enchaînement et la défense.`,fix:`Faire répéter la liaison seule : dernier coup puis esquive en gardant les genoux fléchis, 5 fois au ralenti.`},{error:`Sortie en reculant tout droit.`,fix:`Placer un plot derrière le boxeur comme « obstacle » pour l’obliger à sortir en pas latéral.`},{error:`Garde basse après la défense.`,fix:`Exiger 2 secondes de garde figée à la sortie, contrôlée par un camarade qui compte.`}],criteria:[`Les trois phases (entrée, action, sortie) sont enchaînées sans arrêt visible.`,`La défense réalisée correspond à la carte montrée.`,`Le boxeur finit chaque passage en garde, appuis équilibrés, menton protégé.`],adaptations:{enfants:`Un seul coup puis défense, cartes en couleurs (rouge = retrait, bleu = esquive), couloir réduit à 4 m.`,ados:`Enchaînement de trois coups imposé et deux défenses successives sur deux cartes.`,jeunesAdultes:`Séquence libre de 5 actions minimum à composer et présenter, avec changement de rythme au milieu.`},safety:`Un seul boxeur par couloir en action, les suivants attendent derrière le plot de départ ; couloirs espacés de 2 m.`},{id:44,slug:`observateur-educatif`,module:5,title:`Devenir observateur éducatif`,level:`intermédiaire`,durationMin:20,objective:`Observer un partenaire avec une grille simple, relever des faits précis (et non des jugements) et les restituer clairement.`,prerequisites:[`S’auto-évaluer au miroir`,`Module 4 : gestion de la distance`,`Module 3 : retour en garde après défense`],organisation:{space:`Aire de 4 m × 4 m par trinôme, une chaise ou un plot pour l’observateur à l’extérieur de l’aire.`,material:[`Grille d’observation sur porte-bloc`,`Crayons`,`4 plots par aire`,`Chronomètre`],groups:`Trinômes : un boxeur au shadow, un boxeur qui « fixe la distance » sans toucher, un observateur ; rotation toutes les 2 min.`},schema:{kind:`cooperation`,phases:[`Le boxeur travaille, le partenaire guide la distance`,`L’observateur coche des faits sur sa grille`,`Restitution de 30 secondes puis rotation`]},steps:[`Présenter la grille : trois items observables (garde haute oui/non, retour en garde après chaque série, déplacement après l’action) et la règle « je dis ce que je vois ».`,`Le partenaire se déplace dans l’aire à 2 m minimum ; le boxeur l’accompagne en shadow en gardant la distance et place des enchaînements dans le vide.`,`L’observateur, assis hors de l’aire, coche chaque item à chaque série (bâtonnets) pendant 2 min, sans parler.`,`Restitution : l’observateur lit ses bâtonnets et donne un fait marquant (« 4 fois sur 6 tu es revenu en garde »).`,`Rotation des rôles ; après trois tours, chacun compare ce qu’on a observé chez lui avec sa propre impression.`],decision:`L’observateur choisit le seul fait à restituer en priorité parmi ses notes, celui qui aidera le plus le boxeur.`,corrections:[{error:`Observateur qui donne un avis (« c’était nul », « trop bien »).`,fix:`Reformuler avec lui en fait mesurable : « combien de fois ? à quel moment ? ».`},{error:`Observateur qui commente pendant l’action.`,fix:`Rappeler la règle du silence : il écrit pendant, il parle seulement au coup de sifflet.`}],criteria:[`La grille comporte des bâtonnets pour chacun des trois items.`,`La restitution cite au moins un fait chiffré ou situé dans le temps.`,`Le boxeur observé peut répéter ce qui lui a été dit.`],adaptations:{enfants:`Un seul item à observer (« la garde reste-t-elle en haut ? »), réponse par pouce levé ou baissé à chaque série.`,ados:`Grille à trois items et restitution structurée « un fait, un conseil ».`,jeunesAdultes:`Grille enrichie (rythme, utilisation de l’espace, variété des coups) et restitution de 1 min avec proposition d’exercice correctif.`},safety:`Le partenaire de distance reste à 2 m minimum, jamais de touche ; l’observateur reste hors de l’aire balisée.`},{id:45,slug:`feedback-bienveillant`,module:5,title:`Aider un partenaire par un retour bienveillant`,level:`intermédiaire`,durationMin:20,objective:`Donner à un partenaire un retour utile et encourageant selon la méthode « positif, conseil, encouragement », puis vérifier son effet.`,prerequisites:[`Devenir observateur éducatif`,`Module 2 : enchaînements de trois coups`,`Module 3 : esquives et parades à vide`],organisation:{space:`Aire de 3 m × 3 m par binôme, marquée au sol par 4 plots.`,material:[`Cartes « phrases d’appui » (« J’ai vu que… », « Essaie de… », « Tu progresses sur… »)`,`Plots`,`Chronomètre`],groups:`Binômes de niveau proche ; rôles « boxeur » et « coach » inversés toutes les 3 min.`},schema:{kind:`cooperation`,phases:[`Le boxeur réalise une série de shadow imposée`,`Le coach donne positif, conseil et encouragement`,`Nouvelle série pour vérifier l’effet du conseil`]},steps:[`Expliquer la règle des trois temps du retour : un point positif précis, un seul conseil réalisable, un encouragement ; distribuer les cartes phrases.`,`Le boxeur réalise 45 secondes de shadow avec un enchaînement et une défense imposés ; le coach observe à 2 m.`,`Le coach formule son retour en 3 phrases maximum en s’aidant des cartes ; le boxeur reformule le conseil reçu.`,`Nouvelle série de 45 secondes : le boxeur applique le conseil, le coach vérifie s’il est appliqué.`,`Le coach dit ce qui a changé ; puis le boxeur dit si le conseil était clair et utile ; inversion des rôles.`],decision:`Le coach choisit un seul conseil parmi tout ce qu’il a vu, celui que son partenaire peut corriger tout de suite.`,corrections:[{error:`Donner trois ou quatre conseils à la fois.`,fix:`Limiter avec la règle « une main = un conseil » : le coach lève un seul doigt quand il parle.`},{error:`Commencer par ce qui ne va pas.`,fix:`Imposer la carte « J’ai vu que… » comme première phrase obligatoire.`},{error:`Conseil vague (« sois mieux en garde »).`,fix:`Demander une partie du corps et une action : « monte ton poing arrière à la joue ».`}],criteria:[`Le retour suit l’ordre positif, conseil, encouragement.`,`Le conseil est unique, précis et porte sur une partie du corps ou un moment.`,`Le boxeur reformule le conseil et l’applique visiblement à la série suivante.`],adaptations:{enfants:`Seulement « un bravo et une astuce », avec cartes dessinées ; l’éducateur accompagne chaque binôme une fois.`,ados:`Méthode complète en trois temps, avec un tour où le coach doit retrouver seul ses phrases sans carte.`,jeunesAdultes:`Retour suivi d’une question ouverte au boxeur (« qu’as-tu ressenti ? ») pour construire ensemble la correction.`},safety:`Le coach reste à 2 m, n’intervient jamais physiquement sur le partenaire ; démonstration du conseil uniquement par geste à vide face à lui.`},{id:46,slug:`gerer-ses-emotions-avant-une-rencontre`,module:5,title:`Gérer ses émotions avant une rencontre`,level:`intermédiaire`,durationMin:15,objective:`Reconnaître les signes du stress avant une rencontre éducative et utiliser une routine respiration-visualisation-shadow pour rester lucide.`,prerequisites:[`Construire son échauffement autonome`,`Module 4 : changements de rythme`],organisation:{space:`Salle calme, chaque boxeur sur un tapis ou un emplacement de 2 m × 2 m.`,material:[`Tapis de sol`,`Cartes « météo intérieure » (soleil, nuage, orage)`,`Chronomètre`,`Sifflet`],groups:`Individuel en groupe complet, puis binômes pour la mise en situation.`},schema:{kind:`cooperation`,phases:[`Repérer sa météo intérieure`,`Routine respiration et visualisation`,`Shadow de mise en confiance sous contrainte de temps`]},steps:[`Discussion de 3 min : quels signes avant une rencontre ? (cœur rapide, mains moites, envie de partir) ; chacun choisit sa carte météo du moment.`,`Respiration « 4-4-6 » : inspirer 4 temps, bloquer 4 temps, souffler 6 temps, répétée 5 fois, assis puis debout en garde.`,`Visualisation guidée de 2 min, yeux fermés : entrer dans l’aire, saluer, se mettre en garde, réaliser sa première action préférée.`,`Mise en situation : au sifflet, le boxeur a 20 secondes pour se lever, se mettre en garde et réaliser un enchaînement calme et précis à vide.`,`Retour en binôme : chacun reprend sa carte météo, dit si elle a changé et quelle étape l’a le plus aidé.`],decision:`Le boxeur choisit l’outil (respiration, visualisation ou phrase-clé) qu’il gardera comme routine personnelle avant une rencontre.`,corrections:[{error:`Respiration haute et rapide, épaules qui montent.`,fix:`Main posée sur le ventre : c’est le ventre qui doit gonfler, épaules immobiles.`},{error:`Shadow précipité après le sifflet.`,fix:`Imposer une première respiration complète avant le premier geste, puis un enchaînement lent compté à voix basse.`}],criteria:[`Le boxeur nomme au moins un signe de stress qu’il ressent.`,`La respiration 4-4-6 est réalisée correctement 5 fois de suite.`,`L’enchaînement après le sifflet est exécuté avec la garde haute et sans précipitation visible.`],adaptations:{enfants:`Respiration « souffler la bougie » et visualisation courte (1 min) racontée comme une histoire.`,ados:`Routine complète et rédaction d’une phrase-clé personnelle (« je respire, je regarde, je boxe »).`,jeunesAdultes:`Travail sur la gestion de l’attente (temps mort de 3 min avant l’action) et construction d’une routine écrite d’avant-rencontre.`},safety:`Se relever lentement après la respiration pour éviter les vertiges ; aucun partenaire à moins de 2 m pendant le shadow ; respect de la parole de chacun.`},{id:47,slug:`situation-globale-distance-et-defense`,module:5,title:`Situation globale : distance, attaque et défense à vide`,level:`intermédiaire`,durationMin:20,objective:`Combiner lecture de la distance, entrée avec enchaînement à vide et défense en réponse à un signal du partenaire, dans un échange coopératif sans contact.`,prerequisites:[`Assembler appuis, enchaînements et défense à vide`,`Module 4 : gestion de la distance`,`Module 4 : prise de décision sur signal`],organisation:{space:`Aire de 4 m × 4 m par binôme, une bande centrale de 1,5 m marquée par plots que personne ne franchit.`,material:[`8 plots par aire (dont 4 pour la bande neutre)`,`Chronomètre`,`Sifflet`],groups:`Binômes ; rôles « attaquant » et « signaleur » inversés toutes les 90 secondes.`},schema:{kind:`distance`,phases:[`Approche jusqu’au bord de la bande neutre`,`Enchaînement à vide face au partenaire, sans franchir`,`Défense sur signal puis sortie en angle`]},steps:[`Placer la bande neutre et rappeler qu’elle crée toujours au moins 1,5 m entre les deux boxeurs : on frappe l’air devant soi, jamais vers le partenaire.`,`L’attaquant avance par petits pas jusqu’au bord de la bande et lance un enchaînement de deux coups dans le vide, puis revient en garde.`,`Le signaleur, de l’autre côté de la bande, lève une main ouverte quand l’attaquant termine : l’attaquant réalise une esquive ou un retrait.`,`Ajouter le choix : main gauche levée = sortie à droite, main droite levée = sortie à gauche ; poing fermé = retrait arrière.`,`Séquences de 90 secondes enchaînées, puis débriefing : quel signal a été le plus difficile à lire et pourquoi.`],decision:`L’attaquant lit le signal du partenaire et choisit en moins d’une seconde la défense et le côté de sortie correspondants.`,corrections:[{error:`L’attaquant entre dans la bande neutre en avançant.`,fix:`Arrêter l’action et faire reprendre l’approche avec un pas de moins ; le pied avant s’arrête au plot.`},{error:`Réaction tardive au signal.`,fix:`Faire garder les yeux sur le buste du partenaire et non sur ses propres poings ; réduire l’enchaînement à un coup.`},{error:`Sortie du mauvais côté.`,fix:`Faire répéter 5 fois au ralenti l’association signal-sortie avant de reprendre la vitesse.`}],criteria:[`L’attaquant ne franchit jamais la bande neutre.`,`Au moins 4 réponses sur 5 correspondent au signal donné.`,`Chaque séquence se termine par un retour en garde équilibré hors de la ligne centrale.`],adaptations:{enfants:`Un seul signal (main levée = retrait), bande neutre élargie à 2 m, séquences de 45 secondes.`,ados:`Trois signaux comme décrits, avec score de bonnes réponses à battre d’une rotation à l’autre.`,jeunesAdultes:`Signaux plus discrets (mouvement d’épaule, pas du partenaire) et enchaînements libres de trois coups.`},safety:`La bande neutre de 1,5 m est infranchissable ; aucun coup dirigé vers le partenaire, uniquement dans le vide devant soi ; arrêt au sifflet.`},{id:48,slug:`arbitre-educatif`,module:5,title:`Tenir le rôle d’arbitre éducatif`,level:`avancé`,durationMin:25,objective:`Diriger une séquence d’assaut éducatif sans contact avec les commandements de base, faire respecter les règles de sécurité et rendre une décision argumentée.`,prerequisites:[`Devenir observateur éducatif`,`Situation globale : distance, attaque et défense à vide`,`Module 4 : gestion de la distance`],organisation:{space:`Aire de 5 m × 5 m délimitée par plots, deux coins de couleur (rouge, bleu), une bande neutre centrale de 1,5 m.`,material:[`Plots rouges, bleus et neutres`,`Cartes de décision (rouge, bleu, égalité)`,`Chronomètre`,`Sifflet`,`Fiche des commandements`],groups:`Groupes de cinq : deux boxeurs, un arbitre, deux juges-observateurs ; rotation à chaque reprise.`},schema:{kind:`cooperation`,phases:[`Présentation, salut et commandement « Boxe ! »`,`Direction de la reprise : « Stop ! », rappel de règle, « Boxe ! »`,`Fin de reprise, avis des juges et décision expliquée`]},steps:[`Apprendre les commandements et leurs gestes : « Boxe ! » (début), « Stop ! » (arrêt immédiat), « Break ! » (reculer d’un pas) ; chacun les répète à voix forte.`,`L’arbitre fait saluer les deux boxeurs, vérifie l’espacement de la bande neutre et lance une reprise de 1 min de shadow face à face.`,`Pendant la reprise, il arrête l’action dès qu’un boxeur s’approche de la bande neutre ou baisse la garde, explique la règle en une phrase et relance.`,`Les juges notent sur leur fiche la qualité technique (garde, variété, déplacements) ; à la fin, ils montrent leur carte de décision en même temps.`,`L’arbitre annonce la décision et justifie en une phrase pour chaque boxeur (un point fort, un point à travailler) ; rotation des rôles.`],decision:`L’arbitre décide seul quand interrompre la reprise et doit choisir entre un simple rappel verbal et un « Stop ! » complet selon le risque.`,corrections:[{error:`Commandements trop faibles ou hésitants.`,fix:`Faire répéter les commandements en voix projetée, bras tendu, avant chaque reprise.`},{error:`L’arbitre laisse les boxeurs se rapprocher de la bande neutre.`,fix:`Le placer sur le côté de la bande, perpendiculaire aux boxeurs, pour voir la distance des deux.`},{error:`Décision donnée sans justification.`,fix:`Imposer la formule « Victoire de … parce que … ; à travailler : … ».`}],criteria:[`Les trois commandements sont utilisés au bon moment et compris des boxeurs.`,`Chaque approche dangereuse de la bande neutre provoque un arrêt dans les 2 secondes.`,`La décision finale est accompagnée d’une justification technique pour chaque boxeur.`],adaptations:{enfants:`Seulement « Boxe ! » et « Stop ! », reprise de 30 secondes, et décision remplacée par « un bravo pour chacun ».`,ados:`Rôle complet avec juges ; l’éducateur évalue l’arbitre sur ses commandements et son placement.`,jeunesAdultes:`Gestion de deux reprises avec pause, avertissement formel en cas de non-respect répété, rapport écrit court de l’arbitre.`},safety:`Aucun contact autorisé : bande neutre infranchissable, coups dans le vide uniquement ; le « Stop ! » de l’arbitre ou de l’éducateur arrête tout immédiatement.`},{id:49,slug:`demonstration-assaut-educatif`,module:5,title:`Préparer une démonstration d’assaut éducatif sans contact`,level:`avancé`,durationMin:25,objective:`Concevoir, répéter et présenter en binôme une démonstration chorégraphiée d’assaut éducatif sans contact, montrant attaque, défense, distance et respect.`,prerequisites:[`Situation globale : distance, attaque et défense à vide`,`Aider un partenaire par un retour bienveillant`,`Module 4 : changements de rythme`],organisation:{space:`Aire de 5 m × 5 m par binôme, bande neutre centrale de 1,5 m, zone « public » marquée à 2 m de l’aire.`,material:[`Plots`,`Fiche « scénario » en 6 cases`,`Crayons`,`Chronomètre`,`Tablette pour filmer (facultatif)`],groups:`Binômes de niveau proche ; présentation devant le groupe qui joue le rôle de public et de jury bienveillant.`},schema:{kind:`distance`,phases:[`Écriture du scénario en 6 actions`,`Répétitions miroir de part et d’autre de la bande neutre`,`Présentation au public et retours`]},steps:[`Chaque binôme remplit la fiche scénario : salut, approche, attaque de A et défense de B, attaque de B et défense de A, changement de rythme, salut final.`,`Répétition au ralenti : chaque action de l’un appelle une réponse visible de l’autre, toujours de son côté de la bande neutre, coups dans le vide.`,`Répétition à vitesse moyenne avec comptage à voix basse pour synchroniser ; ajustement des distances au plot près.`,`Répétition générale chronométrée (45 à 60 secondes) avec un autre binôme qui fait un retour « positif, conseil, encouragement ».`,`Présentation devant le groupe : annonce du titre, démonstration, salut ; le public cite ce qu’il a reconnu (esquive, retrait, enchaînement, changement de rythme).`],decision:`Le binôme choisit l’ordre des actions et le moment du changement de rythme pour rendre la démonstration lisible pour le public.`,corrections:[{error:`Coups qui partent vers le partenaire au lieu d’être dans le vide devant soi.`,fix:`Reprendre au ralenti avec un plot sur la bande neutre comme cible visuelle fixe, bras orienté en légère diagonale.`},{error:`Défenses qui arrivent avant l’attaque (manque de synchronisation).`,fix:`Compter à voix haute « un, deux, réponse » pendant les répétitions jusqu’à l’automatisme.`},{error:`Démonstration confuse, actions trop rapides.`,fix:`Ralentir de moitié et marquer chaque fin d’action par une garde figée d’une demi-seconde.`}],criteria:[`Les six cases du scénario sont présentées dans l’ordre prévu.`,`Aucune action ne franchit la bande neutre ni ne vise le partenaire.`,`Le public identifie correctement au moins trois techniques montrées.`],adaptations:{enfants:`Scénario en 4 cases avec images, durée de 30 secondes, l’éducateur compte le rythme à voix haute.`,ados:`Scénario complet en 6 cases avec un titre et une courte présentation orale du binôme.`,jeunesAdultes:`Scénario de 8 actions avec deux changements de rythme et utilisation de tout l’espace de l’aire ; vidéo analysée après coup.`},safety:`Démonstration strictement sans contact : bande neutre de 1,5 m infranchissable, public derrière la ligne à 2 m, arrêt immédiat au sifflet.`},{id:50,slug:`preparer-une-seance-pour-les-plus-jeunes`,module:5,title:`Préparer et animer un atelier pour les plus jeunes`,level:`avancé`,durationMin:25,objective:`Concevoir et animer un atelier court de boxe éducative sans contact pour des plus jeunes, avec consigne claire, démonstration et sécurité.`,prerequisites:[`Aider un partenaire par un retour bienveillant`,`Construire son échauffement autonome`,`Tenir le rôle d’arbitre éducatif`],organisation:{space:`Aire de 6 m × 6 m pour l’atelier, coin préparation avec table ou banc.`,material:[`Fiche « atelier » vierge (but, matériel, consigne, sécurité, variante)`,`Plots, cerceaux, cartes de couleur`,`Chronomètre`,`Sifflet`],groups:`Binômes d’animateurs (ados ou jeunes adultes) ; un groupe de 4 à 6 plus jeunes ou des camarades jouant leur rôle.`},schema:{kind:`cooperation`,phases:[`Préparer la fiche atelier en binôme`,`Démontrer, lancer et faire tourner l’atelier`,`Bilan avec les jeunes puis avec l’éducateur`]},steps:[`En 6 min, le binôme remplit la fiche : un seul but (ex. garder la garde en se déplaçant), le matériel, une consigne en une phrase, la règle de sécurité, une variante plus facile et une plus difficile.`,`Installer l’espace : plots et cerceaux placés avec au moins 1,5 m entre chaque enfant, vérification par l’éducateur.`,`Accueillir le groupe, annoncer le but, démontrer l’exercice une fois lentement et une fois à vitesse normale, puis faire répéter la consigne par un enfant.`,`Animer 6 min : encourager, corriger une seule chose à la fois, utiliser la variante facile ou difficile selon la réussite observée.`,`Clôturer avec les jeunes (« qu’avez-vous appris ? ») puis bilan avec l’éducateur : ce qui a marché, ce qui serait à changer.`],decision:`Pendant l’animation, le binôme décide quand passer à la variante facile ou difficile en observant le nombre d’enfants qui réussissent.`,corrections:[{error:`Consigne trop longue ou avec plusieurs buts.`,fix:`Réécrire la consigne pour qu’elle tienne en une phrase de 15 mots maximum avec un seul verbe d’action.`},{error:`Animateurs qui parlent dos au groupe ou pendant que les enfants bougent.`,fix:`Règle « sifflet, arrêt, regard » : on siffle, tout le monde s’arrête, l’animateur se place face au groupe avant de parler.`},{error:`Oubli de la sécurité dans l’installation.`,fix:`Faire vérifier les espacements au pas (deux grands pas entre chaque enfant) avant le lancement.`}],criteria:[`La fiche atelier est complète (but, matériel, consigne, sécurité, deux variantes).`,`La consigne est reformulée correctement par un enfant avant le lancement.`,`Au moins une adaptation (variante) est utilisée à bon escient pendant l’animation.`],adaptations:{enfants:`Les 9-11 ans les plus avancés co-animent seulement la démonstration avec l’éducateur, sans gérer le groupe.`,ados:`Animation complète en binôme d’un atelier de 6 min pour des 6-9 ans, sous supervision directe.`,jeunesAdultes:`Préparation d’une mini-séance de 15 min (échauffement, atelier, retour au calme) avec fiche écrite archivée au club.`},safety:`L’éducateur du club reste responsable et présent en permanence ; aucun contact entre enfants, espacement minimal de 1,5 m, matériel vérifié avant le début.`}];var E=[...p,...m,...v,...g,...h];var b=`esct_lessons`;function l(s){return Array.isArray(s)?[...new Set(s.filter(e=>Number.isInteger(e)))]:[]}var f=class s{state=ie(this.load());done=oc(()=>new Set(this.state().done));favorites=oc(()=>new Set(this.state().favorites));session=oc(()=>this.state().session);doneCount=oc(()=>this.state().done.length);isDone(e){return this.done().has(e)}isFavorite(e){return this.favorites().has(e)}inSession(e){return this.state().session.includes(e)}toggleDone(e){this.update(r=>F(m$1({},r),{done:x(r.done,e)}))}toggleFavorite(e){this.update(r=>F(m$1({},r),{favorites:x(r.favorites,e)}))}addToSession(e){this.inSession(e)||this.update(r=>F(m$1({},r),{session:[...r.session,e]}))}removeFromSession(e){this.update(r=>F(m$1({},r),{session:r.session.filter(a=>a!==e)}))}moveInSession(e,r){let a=[...this.state().session],o=a.indexOf(e),u=o+r;o<0||u<0||u>=a.length||([a[o],a[u]]=[a[u],a[o]],this.update(q=>F(m$1({},q),{session:a})))}clearSession(){this.update(e=>F(m$1({},e),{session:[]}))}countDone(e){let r=this.done();return e.filter(a=>r.has(a)).length}update(e){this.state.update(e);try{localStorage.setItem(b,JSON.stringify(this.state()))}catch(r){}}load(){try{let e=localStorage.getItem(b),r=e?JSON.parse(e):{};return{done:l(r.done),favorites:l(r.favorites),session:l(r.session)}}catch(e){return{done:[],favorites:[],session:[]}}}static ɵfac=function(r){return new(r||s)};static ɵprov=M({token:s,factory:s.ɵfac,providedIn:`root`})};function x(s,e){return s.includes(e)?s.filter(r=>r!==e):[...s,e]}export{f as n,E as t};